"use client";

import Link from "next/link";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import Image from "next/image";
import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import {
  Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, BookOpen, Building2,
  CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight,
  CircleHelp, ClipboardList, CreditCard, Download, FileCheck2, FileText, Filter,
  GraduationCap, Home, KeyRound, LayoutDashboard, LogOut, Menu, MoreHorizontal,
  Pencil, Plus, Search, Send, Settings, ShieldCheck, Sparkles, Users, Wallet,
  X, UserRound, Landmark, AlertTriangle, Eye, EyeOff, MessageSquare, Receipt, LockKeyhole,
} from "lucide-react";
import {
  activeTerm, createFee, initialAnnouncements, initialAssignments, initialFees, initialStudents,
  initialTeachers, scoreRows, type Announcement, type Assignment, type Fee, type Role,
  type ClassGroup, type Student, type StudentStatus, type Teacher, type TeacherStatus,
} from "@/lib/demo-data";
import { mockApi } from "@/lib/mock-api";
import LandingPage from "@/components/LandingPage";

const navy = "#00022E";
const classes = ["JSS 1", "JSS 2", "SSS 2", "SSS 3"];
const levels = ["JSS1", "JSS2", "SSS1", "SSS2", "SSS3"];
const initials = (name: string) => name.trim().split(/\s+/).slice(0, 2).map(part => part[0]).join("").toUpperCase();
const naira = (amount: number) => `₦${Math.max(0, amount).toLocaleString("en-NG")}`;

type ModalKind = "add-student" | "student-detail" | "add-teacher" | "teacher-detail" | "deactivate-teacher" | "level-fee" | "log-payment" | "new-announcement" | "bulk-download" | "transcript-purchase" | "profile" | "class" | "add-class" | "edit-school" | "publish" | null;
type ToastState = { title: string; detail?: string } | null;
type SchoolAppearance = { fontSize: "small" | "medium" | "large"; primary: string; accent: string };
const termOptions = ["First Term · 2024/2025", "Second Term · 2024/2025", "Third Term · 2024/2025"];

export default function KatalysaApp() {
  const pathname = usePathname();
  const router = useRouter();
  const search = useSearchParams();
  const segments = pathname.split("/").filter(Boolean);
  const roleSegment = segments[0];
  const screen = segments.slice(1).join("/") || "home";

  const [role, setRole] = useState<Role | null>(null);
  const [userName, setUserName] = useState("Amara Okafor");
  const [schoolName, setSchoolName] = useState("Bloomfield Academy");
  const [mobileNav, setMobileNav] = useState(false);
  const [termMenuOpen, setTermMenuOpen] = useState(false);
  const [selectedTerm, setSelectedTerm] = useState(termOptions[0]);
  const [appearance, setAppearance] = useState<SchoolAppearance>({ fontSize: "small", primary: "#00022E", accent: "#FFFFFF" });
  const [modal, setModal] = useState<ModalKind>(null);
  const [toastState, setToastState] = useState<ToastState>(null);
  const [students, setStudents] = useState<Student[]>(initialStudents);
  const [teachers, setTeachers] = useState<Teacher[]>(initialTeachers);
  const [fees, setFees] = useState<Fee[]>(initialFees);
  const [announcements, setAnnouncements] = useState<Announcement[]>(initialAnnouncements);
  const [assignments, setAssignments] = useState<Assignment[]>(initialAssignments);
  const [classGroups, setClassGroups] = useState<ClassGroup[]>([
    {name:"JSS 1",students:18,teacher:"Adebayo Okafor",level:"Junior Secondary",room:"Block A · Room 1"},
    {name:"JSS 2",students:12,teacher:"Funke Adeleke",level:"Junior Secondary",room:"Block A · Room 2"},
    {name:"SSS 2",students:10,teacher:"Adebayo Okafor",level:"Senior Secondary",room:"Block B · Room 2"},
    {name:"SSS 3",students:8,teacher:"Amina Yusuf",level:"Senior Secondary",room:"Block B · Room 3"},
  ]);
  const [selectedStudent, setSelectedStudent] = useState<Student>(initialStudents[0]);
  const [selectedTeacher, setSelectedTeacher] = useState<Teacher>(initialTeachers[0]);
  const [activeChildId, setActiveChildId] = useState(1);
  const [studentFilter, setStudentFilter] = useState<StudentStatus | "all">("all");
  const [teacherFilter, setTeacherFilter] = useState<TeacherStatus>("active");
  const [feeFilter, setFeeFilter] = useState("all");
  const [searchText, setSearchText] = useState("");
  const [setupDone, setSetupDone] = useState([true, true, true, true, false, false, false]);
  const [scoreValues, setScoreValues] = useState<Record<string, number>>({
    "1-ca1": 18, "1-ca2": 15, "1-exam": 52, "2-ca1": 19, "2-ca2": 17, "2-exam": 55,
  });
  const [published, setPublished] = useState(false);
  const [schoolGates, setSchoolGates] = useState({ view: true, download: true });
  const [smsEnabled, setSmsEnabled] = useState(false);
  const [profileSaved, setProfileSaved] = useState(false);
  const [feeAmountInput, setFeeAmountInput] = useState("25000");
  const [sessionReady, setSessionReady] = useState(false);
  const [schoolSubdomain, setSchoolSubdomain] = useState("");
  const [callbackResult, setCallbackResult] = useState<{status:string;purpose:string;total_amount?:number;student_id?:number}|null>(null);

  useEffect(() => {
    const host = window.location.hostname.toLowerCase();
    const subdomain = host.endsWith(".katalysa.ng") ? host.slice(0, -".katalysa.ng".length).split(".").pop() || "" : new URLSearchParams(window.location.search).get("school") || "";
    if (subdomain && subdomain !== "www") setSchoolSubdomain(subdomain);
    const savedAppearance = window.localStorage.getItem("katalysa-school-appearance");
    if (savedAppearance) {
      try { setAppearance({ ...appearance, ...JSON.parse(savedAppearance) }); } catch { window.localStorage.removeItem("katalysa-school-appearance"); }
    }
    const raw = window.localStorage.getItem("katalysa-demo-session");
    if (raw) {
      try {
        const session = JSON.parse(raw) as { role: Role; name: string; must_change_password?: boolean };
        setRole(session.role); setUserName(session.name);
      } catch { window.localStorage.removeItem("katalysa-demo-session"); }
    }
    setSessionReady(true);
  }, []);

  useEffect(() => {
    document.documentElement.style.setProperty("--navy", appearance.primary);
    document.documentElement.style.setProperty("--school-accent", appearance.accent);
    document.documentElement.dataset.schoolFontSize = appearance.fontSize;
    window.localStorage.setItem("katalysa-school-appearance", JSON.stringify(appearance));
  }, [appearance]);

  const callbackReference = search.get("reference") || "";
  useEffect(() => {
    if (segments[0] === "payment" && segments[1] === "callback" && callbackReference) {
      mockApi.verifyPayment(callbackReference).then(result=>{
        setCallbackResult(result);
        if(result.status==="success"&&result.purpose==="fee"&&result.student_id&&result.total_amount){
          setFees(old=>old.map(fee=>fee.studentId===result.student_id?{...fee,paid:Math.min(fee.totalPayable,fee.paid+result.total_amount!)}:fee));
        }
      });
    }
  }, [pathname, callbackReference]);

  useEffect(() => {
    if (!toastState) return;
    const timer = window.setTimeout(() => setToastState(null), 3400);
    return () => window.clearTimeout(timer);
  }, [toastState]);

  const childList = students.filter(student => student.parent === "Mrs Okafor");
  const selectedChild = childList.find(child => child.id === activeChildId) || childList[0] || students[0];
  const myFee = fees.find(record => record.studentId === selectedChild?.id) || fees[0];
  const shownStudents = useMemo(() => students.filter(student =>
    (studentFilter === "all" || student.status === studentFilter) &&
    `${student.name} ${student.admission} ${student.className} ${student.parent}`.toLowerCase().includes(searchText.toLowerCase())
  ), [students, studentFilter, searchText]);
  const shownTeachers = useMemo(() => teachers.filter(teacher => teacher.status === teacherFilter &&
    `${teacher.name} ${teacher.phone} ${teacher.email}`.toLowerCase().includes(searchText.toLowerCase())
  ), [teachers, teacherFilter, searchText]);
  const shownFees = useMemo(() => fees.filter(fee =>
    (feeFilter === "all" || (feeFilter === "outstanding" ? fee.balance > 0 : fee.status === feeFilter)) &&
    `${fee.student} ${fee.className}`.toLowerCase().includes(searchText.toLowerCase())
  ), [fees, feeFilter, searchText]);

  const notify = (title: string, detail = "Simulated in demo mode. No real account was changed.") => setToastState({ title, detail });
  const go = (path: string) => { setMobileNav(false); setSearchText(""); router.push(path); };
  const roleHome = (nextRole: Role) => nextRole === "admin" ? "/admin" : `/${nextRole}`;
  const signIn = async (nextRole: Role, name?: string, selectedSchool?: string) => {
    const session = await mockApi.login(nextRole, name);
    if (selectedSchool) setSchoolName(selectedSchool);
    setRole(nextRole); setUserName(session.name);
    router.push(session.must_change_password ? "/change-password" : roleHome(nextRole));
  };
  const signOut = () => {
    window.localStorage.removeItem("katalysa-demo-session");
    setRole(null); setUserName("Amara Okafor"); router.push("/login");
  };
  const finishSetup = (index: number) => setSetupDone(previous => previous.map((done, i) => i === index ? !done : done));
  const openStudent = (student: Student) => { setSelectedStudent(student); setModal("student-detail"); };
  const openTeacher = (teacher: Teacher) => { setSelectedTeacher(teacher); setModal("teacher-detail"); };

  const openPayment = async (purpose: "fee" | "transcript", amount?: number, studentId = selectedChild?.id) => {
    const total = purpose === "transcript" ? 5175 : amount || Math.min(Math.max(1000, Number(feeAmountInput)), Math.max(1000, myFee.balance));
    const created = await mockApi.createPayment(purpose, total, studentId);
    router.push(created.authorization_url);
  };

  const closeModal = () => setModal(null);
  const submitForm = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const value = (key: string) => String(form.get(key) || "").trim();
    if (modal === "add-student") {
      const name = value("name"), className = value("className") || "JSS 1";
      const newStudent: Student = { id: Date.now(), name, admission: `BSA/2026/${String(students.length + 1).padStart(3,"0")}`, className, level: className.startsWith("SSS")?"SSS1":"JSS1", status:"active", parent:value("parent"), phone:value("phone"), email:value("email"), dob:value("dob") || "—", sex:value("sex") || "Female", colour:"gold", average:0 };
      setStudents(old => [newStudent, ...old]); setFees(old => [{ id:Date.now(), studentId:newStudent.id, student:newStudent.name, className, term:activeTerm, academicFee:50000, allowance:5000, paid:0, get totalPayable(){return this.academicFee+this.allowance;}, get balance(){return this.totalPayable-this.paid;}, get status(){return this.paid===0?"unpaid":"partial";} }, ...old]);
      setModal(null); notify("Student registered", `${name} added to ${className} in this demo.`);
    } else if (modal === "add-teacher") {
      const name=value("name"); setTeachers(old=>[{id:Date.now(),name,phone:value("phone"),email:value("email"),status:"active",assignments:[]},...old]);
      setModal(null); notify("Teacher account prepared", "This is a local preview; no invitation or login was sent.");
    } else if (modal === "deactivate-teacher") {
      setTeachers(old=>old.map(teacher=>teacher.id===selectedTeacher.id?{...teacher,status:"inactive",dateLeft:value("dateLeft"),reason:value("reason")}:teacher));
      setModal(null); notify("Teacher marked inactive", "The status change is local to this demo.");
    } else if (modal === "level-fee") {
      const level=value("level"),academicFee=Number(value("academicFee")),allowance=Number(value("allowance"));
      setFees(old=>old.map(record=>{const student=students.find(item=>item.id===record.studentId);return student?.level===level?createFee(record.id,record.studentId,record.student,record.className,academicFee,allowance,record.paid,record.term):record;}));
      notify("Level fees updated", `Illustrative fee set for ${level} in ${value("term")}.`); setModal(null);
    } else if (modal === "log-payment") {
      const target=students.find(student=>student.id===Number(value("studentId")))||students[0];
      const amount=Number(value("amount")); setFees(old=>old.map(fee=>fee.studentId===target.id?{...fee,paid:fee.paid+amount}:fee));
      setModal(null); notify("Payment recorded", `${naira(amount)} added to the sample fee ledger. No SMS or receipt was actually sent.`);
    } else if (modal === "new-announcement") {
      setAnnouncements(old=>[{id:Date.now(),title:value("title"),body:value("body"),audience:value("audience") as Announcement["audience"],sendSms:form.get("sendSms")==="on",date:"Just now"},...old]);
      setModal(null); notify("Announcement posted", "It is visible in the demo only; no SMS was sent.");
    } else if (modal === "publish") {
      setPublished(true); setModal(null); notify("Results published in demo", "No parents were notified and no results were sent to the backend.");
    } else if (modal === "edit-school") {
      setSchoolName(value("schoolName") || schoolName); setProfileSaved(true); setModal(null); notify("School profile saved", "Changes are local to this browser demo.");
    } else if (modal === "profile") {
      setUserName(value("fullName") || userName); setModal(null); notify("Profile saved", "Changes are local to this browser demo.");
    } else if (modal === "transcript-purchase") {
      setModal(null); void openPayment("transcript");
    } else {
      setModal(null); notify("Saved", "This update is simulated in the prototype.");
    }
  };

  if (!sessionReady) return <main className="loading"><span className="spinner" /> Loading Katalysa demo…</main>;
  if (schoolSubdomain && (!roleSegment || roleSegment === "register")) return <LoginScreen onLogin={signIn} schoolSubdomain={schoolSubdomain}/>;
  if (role && roleSegment === "change-password") return <ChangePasswordScreen onComplete={async()=>{await mockApi.changePassword();notify("Password changed in demo");router.push(roleHome(role));}} onSkip={async()=>{await mockApi.continueWithoutPasswordChange();notify("Password change postponed", "You can continue exploring the parent dashboard.");router.push(roleHome(role));}}/>;
  if (roleSegment === "login") return <LoginScreen onLogin={signIn} onRegister={()=>router.push("/register")} schoolSubdomain={schoolSubdomain} mode={segments[1] === "staff" || segments[1] === "parent" ? segments[1] : null} />;
  if (roleSegment === "register") return <RegisterScreen schoolName={schoolName} setSchoolName={setSchoolName} onRegister={async(name,adminName)=>{await mockApi.registerSchool(name,adminName);setRole("admin");setUserName(adminName);setSchoolName(name);router.push("/admin/school-setup");notify("School registered in demo", "No account or school tenant was created in the backend.");}} />;
  if (!roleSegment) return <LandingPage onLogin={()=>router.push("/login")} onGetStarted={()=>router.push("/register")}/>;
  if (!role || (roleSegment === "register" && !role)) {
    if (roleSegment === "change-password") return <ChangePasswordScreen onComplete={async()=>{await mockApi.changePassword();notify("Password changed in demo");router.push("/");}} onSkip={async()=>{await mockApi.continueWithoutPasswordChange();router.push("/");}} />;
    if (roleSegment === "demo-checkout") return <DemoCheckout reference={search.get("reference")||""} onComplete={async reference=>{await mockApi.completeDemoPayment(reference);router.push(`/payment/callback?reference=${encodeURIComponent(reference)}`);}} onCancel={()=>router.back()} />;
    return <LoginScreen onLogin={signIn} onRegister={()=>router.push("/register")} />;
  }

  if (roleSegment === "demo-checkout") return <DemoCheckout reference={search.get("reference")||""} onComplete={async reference=>{await mockApi.completeDemoPayment(reference);router.push(`/payment/callback?reference=${encodeURIComponent(reference)}`);}} onCancel={()=>router.back()} />;
  if (roleSegment === "payment" && segments[1] === "callback") return <PaymentCallback result={callbackResult} goFees={()=>router.push("/parent/fees")} goTranscript={()=>router.push("/parent/transcript")} />;

  const base = role === "admin" ? "/admin" : `/${role}`;
  const activeLabel = role === "admin" ? adminLabels[screen] || "Overview" : role === "teacher" ? teacherLabels[screen] || "Home" : parentLabels[screen] || "Home";
  const showModalContent = () => {
    if (modal === "add-student") return <Modal title="Register a student" onClose={closeModal} onSubmit={submitForm} submit="Register student"><div className="form-grid">{Field("Student full name","name","e.g. Ada Okafor",true)}{Field("Admission number","admission","Auto-generated for demo")}<label>Class<select name="className" defaultValue="JSS 1">{classes.map(c=><option key={c}>{c}</option>)}</select></label><label>Sex<select name="sex"><option>Female</option><option>Male</option></select></label>{Field("Date of birth","dob","",false,"date")}{Field("Parent / guardian","parent","Parent name",true)}{Field("Parent phone","phone","0800 000 0000",true,"tel")}{Field("Parent email","email","parent@example.com",false,"email")}</div><p className="note">A linked parent account will be represented in this demo; no SMS credentials are generated.</p></Modal>;
    if (modal === "student-detail") return <Modal title={selectedStudent.name} onClose={closeModal} onSubmit={submitForm} submit="Done" showSubmit={false}><div className="detail-hero"><Avatar name={selectedStudent.name} colour={selectedStudent.colour}/><div><p className="detail-title">{selectedStudent.className} <Status value={selectedStudent.status}/></p><p className="subtle">Admission {selectedStudent.admission} · {selectedStudent.dob} · {selectedStudent.sex}</p></div></div><h4 className="section-kicker">PARENT / GUARDIAN</h4><div className="detail-grid"><span>Name<strong>{selectedStudent.parent}</strong></span><span>Phone<strong>{selectedStudent.phone}</strong></span><span>Email<strong>{selectedStudent.email}</strong></span></div><h4 className="section-kicker">UPDATE STATUS</h4><div className="status-actions">{(["active","graduated","withdrawn","inactive"] as StudentStatus[]).filter(status=>status!==selectedStudent.status).map(status=><button key={status} className="button button-outline" onClick={()=>{setStudents(old=>old.map(student=>student.id===selectedStudent.id?{...student,status}:student));setSelectedStudent(old=>({...old,status}));notify(`Student marked ${status}`);}}>{status==="active"?"Reactivate":`Mark ${status}`}</button>)}</div><h4 className="section-kicker">ACADEMIC SNAPSHOT</h4><div className="detail-grid"><span>Term average<strong>{selectedStudent.average}%</strong></span><span>Fee balance<strong>{naira(fees.find(f=>f.studentId===selectedStudent.id)?.balance||0)}</strong></span></div></Modal>;
    if (modal === "add-teacher") return <Modal title="Add a teacher" onClose={closeModal} onSubmit={submitForm} submit="Create teacher"><div className="form-grid">{Field("Full name","name","e.g. Chika Eze",true)}{Field("Phone number","phone","0800 000 0000",true,"tel")}{Field("Email","email","teacher@school.com",false,"email")}<label>Initial account password<input name="password" type="text" value="DemoPass123" readOnly /></label></div><p className="note">In the real service a teacher account is created and must change this password after first login. This prototype does not send credentials.</p></Modal>;
    if (modal === "teacher-detail") return <Modal title="Teacher details" onClose={closeModal} onSubmit={submitForm} submit="Close" showSubmit={false}><div className="detail-hero"><Avatar name={selectedTeacher.name} colour="violet"/><div><p className="detail-title">{selectedTeacher.name} <Status value={selectedTeacher.status}/></p><p className="subtle">{selectedTeacher.phone} · {selectedTeacher.email}</p></div></div><h4 className="section-kicker">ASSIGNMENTS</h4>{selectedTeacher.assignments.length?selectedTeacher.assignments.map(item=><div className="assignment-row" key={item}><BookOpen size={16}/>{item}<button className="icon-action" onClick={()=>{setTeachers(old=>old.map(t=>t.id===selectedTeacher.id?{...t,assignments:t.assignments.filter(a=>a!==item)}:t));notify("Assignment removed from demo");}}>×</button></div>):<Empty title="No assignments yet" action="Assign a class" onAction={()=>{setModal("class");}}/>}<button className="button button-outline mt-12" onClick={()=>setModal("class")}><Plus size={15}/> Add assignment</button><div className="modal-actions-left">{selectedTeacher.status==="active"?<button className="button button-danger" onClick={()=>setModal("deactivate-teacher")}>Deactivate teacher</button>:<button className="button button-primary" onClick={()=>{setTeachers(old=>old.map(t=>t.id===selectedTeacher.id?{...t,status:"active",dateLeft:undefined,reason:undefined}:t));setSelectedTeacher(old=>({...old,status:"active"}));setModal(null);notify("Teacher reactivated", "Account status is local to this demo.");}}>Reactivate teacher</button>}</div></Modal>;
    if (modal === "deactivate-teacher") return <Modal title="Deactivate teacher" onClose={closeModal} onSubmit={submitForm} submit="Confirm deactivation"><p className="form-intro">The teacher will be unable to sign in after deactivation. In this prototype the change only affects the local directory.</p><div className="form-grid">{Field("Date left","dateLeft","",true,"date")}{Field("Reason","reason","e.g. Relocated",true)}</div></Modal>;
    if (modal === "level-fee") return <Modal title="Set fee by class level" onClose={closeModal} onSubmit={submitForm} submit="Set fees for this level"><p className="form-intro">The fee and allowance are combined into a single total payable for parents. The allowance is never shown as a separate parent charge.</p><div className="form-grid"><label>Level<select name="level">{levels.map(level=><option key={level}>{level}</option>)}</select></label><label>Term<select name="term"><option>{activeTerm}</option></select></label>{Field("Academic fee (₦)","academicFee","50000",true,"number")}{Field("Processing allowance (₦)","allowance","5000",true,"number")}</div><p className="note">Covers matching classes: JSS 1 · JSS 2 · SSS 1. Demo values only.</p></Modal>;
    if (modal === "log-payment") return <Modal title="Log a fee payment" onClose={closeModal} onSubmit={submitForm} submit="Record payment"><div className="form-grid"><label>Student<select name="studentId">{students.filter(student=>student.status==="active").map(student=><option value={student.id} key={student.id}>{student.name} · {student.className}</option>)}</select></label>{Field("Amount received (₦)","amount","e.g. 25000",true,"number")}<label>Payment method<select name="method"><option>Bank transfer</option><option>Cash</option><option>POS</option></select></label>{Field("Payment date","date","",false,"date")}{Field("Reference (optional)","reference","Bank/POS reference")}</div><p className="note">The real backend queues an SMS receipt. This demo records a local payment only and does not send SMS or create a PDF.</p></Modal>;
    if (modal === "new-announcement") return <Modal title="New announcement" onClose={closeModal} onSubmit={submitForm} submit="Post announcement"><div className="form-grid">{Field("Title","title","e.g. School closes early Friday",true)}<label>Audience<select name="audience"><option value="all">Everyone</option><option value="parents">Parents only</option><option value="teachers">Teachers only</option></select></label><label className="full-span">Message<textarea name="body" rows={4} required placeholder="Write a clear update for your school community…" /></label><label className="check-label full-span"><input type="checkbox" name="sendSms"/> Also send by SMS <span>Demo only; SMS is not sent.</span></label></div></Modal>;
    if (modal === "bulk-download") return <Modal title="Download results" onClose={closeModal} onSubmit={event=>{event.preventDefault();setModal(null);notify("Download prepared", "A sample PDF or ZIP would be returned by the real API.");}} submit="Prepare demo download"><div className="form-grid"><label>Term<select name="term"><option>{activeTerm}</option></select></label><label>Class<select name="className"><option value="">Choose a class</option>{classes.map(c=><option key={c}>{c}</option>)}</select></label><label className="full-span">Student (optional)<select name="studentId"><option value="">Entire class / choose student</option>{students.map(student=><option key={student.id} value={student.id}>{student.name} · {student.className}</option>)}</select></label></div><p className="note">Choose one student for a PDF, or a class for a ZIP bundle. Actual downloads are not created in demo mode.</p></Modal>;
    if (modal === "transcript-purchase") return <Modal title="Transcript payment" onClose={closeModal} onSubmit={submitForm} submit="Continue to demo checkout"><div className="itemized"><div><span>Transcript fee</span><strong>₦5,000</strong></div><div><span>Estimated Paystack charges</span><strong>₦175</strong></div><div className="itemized-total"><span>Total to pay</span><strong>₦5,175</strong></div></div><p className="note">Transcript payments use an itemized estimate. Continuing opens a simulated checkout; no payment provider is contacted.</p></Modal>;
    if (modal === "profile") return <Modal title="Your profile" onClose={closeModal} onSubmit={submitForm} submit="Save profile"><div className="form-grid">{Field("Full name","fullName",userName,true,userName)}<label>Phone number<input value="08077771111" readOnly/></label>{Field("Email","email","you@school.com",false,"mrsokafor@gmail.com")}</div><p className="note">Parents can update name and email. Phone number changes go through the school admin. Prototype changes stay local.</p><button type="button" className="text-button" onClick={()=>{setModal(null);router.push("/change-password");}}>Change password →</button></Modal>;
    if (modal === "add-class") return <Modal title="Create a class" onClose={closeModal} onSubmit={event=>{event.preventDefault();const data=new FormData(event.currentTarget);const name=String(data.get("className")||"").trim();if(!name)return;setClassGroups(current=>[{name,students:0,teacher:String(data.get("teacher")||"Unassigned"),level:String(data.get("level")||"Junior Secondary"),room:String(data.get("room")||"")},...current]);setModal(null);notify("Class created in demo", `${name} has been added to the class directory.`);}} submit="Create class"><div className="form-grid">{Field("Class name","className","e.g. JSS 1",true)}<label>Level<select name="level">{levels.map(level=><option key={level}>{level}</option>)}</select></label><label>Class teacher<select name="teacher"><option>Unassigned</option>{teachers.filter(t=>t.status==="active").map(t=><option key={t.id}>{t.name}</option>)}</select></label>{Field("Room","room","e.g. Block A · Room 02")}{Field("Capacity","capacity","30",true,"number")}</div></Modal>;
    if (modal === "class") return <Modal title="Add teacher assignment" onClose={closeModal} onSubmit={event=>{event.preventDefault();const form=new FormData(event.currentTarget);const item=`${form.get("subject")} · ${form.get("className")}${form.get("formTeacher")==="on"?" · Class Teacher":""}`;setTeachers(old=>old.map(t=>t.id===selectedTeacher.id?{...t,assignments:[...t.assignments,item]}:t));setSelectedTeacher(old=>({...old,assignments:[...old.assignments,item]}));setModal("teacher-detail");notify("Assignment added in demo");}} submit="Add assignment"><div className="form-grid"><label>Subject<select name="subject">{["Mathematics","English","Basic Science","Social Studies","Civic Education"].map(s=><option key={s}>{s}</option>)}</select></label><label>Class<select name="className">{classes.map(c=><option key={c}>{c}</option>)}</select></label><label className="check-label full-span"><input type="checkbox" name="formTeacher"/> Assign as class teacher</label></div></Modal>;
    if (modal === "edit-school") return <Modal title="School profile" onClose={closeModal} onSubmit={submitForm} submit="Save school profile"><div className="form-grid">{Field("School name","schoolName","Bloomfield Academy",true,schoolName)}{Field("Phone number","schoolPhone","0800 000 0000",true,"08035550100")}{Field("Address","address","14 Independence Avenue",true,"14 Independence Avenue, Ikeja")}{Field("State","state","",false,"text","Lagos")}<label>LGA<select name="lga"><option>Ikeja</option><option>Eti-Osa</option><option>Surulere</option></select></label><label>School type<select name="schoolType"><option>Both</option><option>Primary</option><option>Secondary</option></select></label></div></Modal>;
    if (modal === "publish") return <Modal title="Publish term results" onClose={closeModal} onSubmit={submitForm} submit="Publish in demo"><div className="warning-box"><AlertTriangle/><p><strong>Publishing locks all scores and notifies parents.</strong><br/>This simulation will mark the term published locally only. Nothing is sent to the backend.</p></div><p className="form-intro">There are no incomplete assignment groups in this demo. Confirm to preview the final step.</p></Modal>;
    return null;
  };

  const renderScreen = () => {
    if (role === "admin") {
      switch (screen) {
        case "home": return <AdminHome students={students} fees={fees} onNewStudent={()=>setModal("add-student")} onLogPayment={()=>setModal("log-payment")} onLevelFee={()=>setModal("level-fee")} onNewAnnouncement={()=>setModal("new-announcement")} onNavigate={go}/>;
        case "school-setup": return <SchoolSetup done={setupDone} onToggle={finishSetup} onNavigate={go}/>;
        case "students": return <StudentsScreen students={shownStudents} filter={studentFilter} setFilter={setStudentFilter} search={searchText} setSearch={setSearchText} onAdd={()=>setModal("add-student")} onOpen={openStudent} onExport={()=>notify("Student list exported", "A sample CSV would download from the backend.")}/>;
        case "teachers": return <TeachersScreen teachers={shownTeachers} filter={teacherFilter} setFilter={v=>{setTeacherFilter(v);setSearchText("");}} search={searchText} setSearch={setSearchText} onAdd={()=>setModal("add-teacher")} onOpen={openTeacher}/>;
        case "classes": return <ClassesScreen groups={classGroups} published={published} onAdd={()=>setModal("add-class")} onEditTerms={()=>notify("Academic calendar", "Term date editing is represented as a demo interaction.")}/>;
        case "fees": return <AdminFees fees={shownFees} filter={feeFilter} setFilter={v=>{setFeeFilter(v);setSearchText("");}} search={searchText} setSearch={setSearchText} onLevelFee={()=>setModal("level-fee")} onLogPayment={()=>setModal("log-payment")} onExport={()=>notify("Fee records exported", "A sample CSV would download from the backend.")}/>;
        case "results": return <AdminResults assignments={assignments} published={published} onComplete={()=>setAssignments(old=>old.map(a=>({...a,complete:a.students})))} onPublish={()=>setModal("publish")} onDownload={()=>setModal("bulk-download")} onSaveScores={()=>notify("Scores saved", "Sample score changes stay in the browser.")}/>;
        case "transcripts": return <AdminTranscripts students={students} onPurchase={()=>notify("Transcript purchase recorded", "This action is simulated; no payment was logged.")}/>;
        case "announcements": return <AnnouncementsScreen announcements={announcements} onNew={()=>setModal("new-announcement")} onDelete={id=>{setAnnouncements(old=>old.filter(a=>a.id!==id));notify("Announcement removed in demo");}} role="admin"/>;
        case "parents": return <ParentsScreen students={students} onUpdate={student=>{setSelectedStudent(student);setModal("student-detail");}}/>;
        case "settings": return <SchoolSettings gates={schoolGates} setGates={setSchoolGates} smsEnabled={smsEnabled} setSmsEnabled={setSmsEnabled} appearance={appearance} setAppearance={setAppearance} onEdit={()=>setModal("edit-school")} onSave={()=>{setProfileSaved(true);notify("Settings saved", "Appearance and settings are saved locally in this prototype.");}} saved={profileSaved}/>;
        case "subscription": return <SubscriptionScreen onChoose={plan=>notify(`${plan} plan selected`, "No subscription or payment is changed in demo mode.")}/>;
        default: return <NotFound onHome={()=>go("/admin")}/>;
      }
    }
    if (role === "teacher") {
      if (screen === "home") return <TeacherHome teacherName={userName} assignments={assignments} onOpen={()=>go("/teacher/classes")}/>;
      if (screen === "classes") return <TeacherClasses assignments={assignments} onOpen={()=>go("/teacher/score-entry")}/>;
      if (screen === "score-entry") return <ScoreEntry values={scoreValues} setValues={setScoreValues} assignments={assignments} onSave={()=>notify("Scores saved", "Scores and zero warnings are shown in this browser only.")}/>;
      if (screen === "announcements") return <AnnouncementsScreen announcements={announcements.filter(a=>a.audience!=="parents")} role="teacher"/>;
      return <NotFound onHome={()=>go("/teacher")}/>;
    }
    if (screen === "home") return <ParentHome child={selectedChild} children={childList} setChild={id=>setActiveChildId(id)} fee={myFee} gates={schoolGates} announcements={announcements.filter(a=>a.audience!=="teachers")} go={go} onPay={amount=>void openPayment("fee",amount)} onReceipt={()=>notify("Payment receipt", "A sample PDF receipt would download from the backend.")}/>;
    if (screen === "results") return <ParentResults child={selectedChild} fee={myFee} gates={schoolGates} onDownload={()=>notify("Result sheet PDF", "A sample PDF would download from the backend.")} onPay={()=>void openPayment("fee",myFee.balance)}/>;
    if (screen === "fees") return <ParentFees child={selectedChild} children={childList} fee={myFee} setChild={id=>setActiveChildId(id)} amount={feeAmountInput} setAmount={setFeeAmountInput} onPay={()=>void openPayment("fee",Number(feeAmountInput))} onHistory={()=>notify("Payment history", "Sample payment records are listed here in the live product.")} onReceipt={()=>notify("Payment receipt", "A sample PDF receipt would download from the backend.")}/>;
    if (screen === "announcements") return <AnnouncementsScreen announcements={announcements.filter(a=>a.audience!=="teachers")} role="parent"/>;
    if (screen === "transcript") return <ParentTranscript child={selectedChild} onDownload={()=>notify("Transcript download", "A sample PDF would download from the backend.")} onPurchase={()=>setModal("transcript-purchase")}/>;
    if (screen === "profile") return <ParentProfile name={userName} onEdit={()=>setModal("profile")} onPassword={()=>router.push("/change-password")}/>;
    return <NotFound onHome={()=>go("/parent")}/>;
  };

  return <div className={`app-frame ${role}-frame`}
    onTouchStart={event=>{
      event.currentTarget.dataset.swipeStartX=String(event.touches[0]?.clientX || 0);
      event.currentTarget.dataset.swipeStartY=String(event.touches[0]?.clientY || 0);
    }}
    onTouchEnd={event=>{
      if(role!=="admin" || mobileNav) return;
      const startX=Number(event.currentTarget.dataset.swipeStartX || 0);
      const startY=Number(event.currentTarget.dataset.swipeStartY || 0);
      const endX=event.changedTouches[0]?.clientX || 0;
      const endY=event.changedTouches[0]?.clientY || 0;
      if(startX<=32 && endX-startX>60 && Math.abs(endY-startY)<70) setMobileNav(true);
    }}>
    {role === "admin" && <button className={`mobile-nav-scrim ${mobileNav ? "is-visible" : ""}`} aria-label="Close navigation" onClick={()=>setMobileNav(false)} onTouchStart={event=>{event.currentTarget.dataset.startX=String(event.touches[0]?.clientX || 0);}} onTouchEnd={event=>{const start=Number(event.currentTarget.dataset.startX || 0);if(start-event.changedTouches[0]?.clientX>35)setMobileNav(false);}}/>}
    {role === "admin" && <aside className={`sidebar ${mobileNav?"sidebar-open":""}`}>
      <Link className="brand" href="/admin"><KatalysaLogo inverse/><span>Katalysa<span className="brand-period">.</span></span></Link>
      <button className="school-switch" onClick={()=>setModal("edit-school")}><span className="school-monogram">B</span><span className="school-meta"><strong>{schoolName}</strong><small>School administrator</small></span><ChevronDown size={15}/></button>
      <div className="sidebar-scroll"><div className="nav-caption">WORKSPACE</div><nav className="side-nav">{adminNavigation.slice(0,5).map(item=><NavItem key={item.path} item={item} active={screen===item.path} onClick={()=>go(`/admin${item.path?`/${item.path}`:""}`)}/>)}</nav>
      <div className="nav-caption gap-top">ACADEMICS</div><nav className="side-nav">{adminNavigation.slice(5,8).map(item=><NavItem key={item.path} item={item} active={screen===item.path} onClick={()=>go(`/admin/${item.path}`)}/>)}</nav>
      <div className="nav-caption gap-top">SCHOOL COMMUNITY</div><nav className="side-nav">{adminNavigation.slice(8,10).map(item=><NavItem key={item.path} item={item} active={screen===item.path} onClick={()=>go(`/admin/${item.path}`)}/>)}</nav>
      <div className="side-spacer"/><div className="setup-mini" onClick={()=>go("/admin/school-setup")} role="button" tabIndex={0}><div className="setup-mini-head"><span><ShieldCheck size={15}/>School setup</span><strong>{setupDone.filter(Boolean).length}/7</strong></div><div className="meter"><span style={{width:`${setupDone.filter(Boolean).length/7*100}%`}}/></div><small>Finish the essentials to get started</small></div>
      <nav className="side-nav foot-nav">{adminNavigation.slice(10,12).map(item=><NavItem key={item.path} item={item} active={screen===item.path} onClick={()=>go(`/admin/${item.path}`)}/>)}</nav></div>
      <UserMenu name={userName} role="School administrator" onProfile={()=>setModal("profile")} onLogout={signOut}/>
    </aside>}
    <div className="main-column">
      <header className={`topbar ${role}-topbar`}>
        {role === "admin" ? <button className="mobile-menu" aria-label="Open navigation" onClick={()=>setMobileNav(!mobileNav)}><Menu/></button> : <Link className="brand compact-brand" href={roleHome(role)}><KatalysaLogo/>Katalysa<span className="brand-period">.</span></Link>}
        <div className="breadcrumbs">{schoolName}<ChevronRight size={14}/><strong>{activeLabel}</strong></div>
        <div className="topbar-right"><div className="term-selector"><button className="term-pill" aria-expanded={termMenuOpen} onClick={()=>setTermMenuOpen(open=>!open)}><span className="green-dot"/>{selectedTerm}<ChevronDown size={13}/></button>{termMenuOpen&&<div className="term-menu">{termOptions.map(term=><button key={term} className={term===selectedTerm?"selected":""} onClick={()=>{setSelectedTerm(term);setTermMenuOpen(false);}}>{term===selectedTerm&&<Check size={13}/>} {term}</button>)}</div>}</div><button className="icon-button" aria-label="Notifications" onClick={()=>notify("You’re all caught up", "Notifications in this prototype are sample content.")}><Bell size={17}/><i/></button>{role!=="admin"&&<button className="icon-button" aria-label="Log out" onClick={signOut}><LogOut size={17}/></button>}<button className="top-user" onClick={()=>setModal("profile")}><Avatar name={userName} colour="gold"/><ChevronDown size={13}/></button></div>
      </header>
      {role === "teacher" && <nav className="teacher-nav"><button className={screen==="home"?"selected":""} onClick={()=>go("/teacher")}>Home</button><button className={screen.startsWith("classes")||screen==="score-entry"?"selected":""} onClick={()=>go("/teacher/classes")}>My classes</button><button className={screen==="announcements"?"selected":""} onClick={()=>go("/teacher/announcements")}>Announcements</button></nav>}
      <main className={`screen-content ${role}-content`} key={`${role}-${screen}`}>
        {role === "teacher" && <div className="teacher-welcome"><span className="eyebrow">{activeTerm} <span className="green-dot"/> Active</span><span className="term-caption"><CalendarDays size={14}/>Academic year 2024/2025</span></div>}
        {renderScreen()}
        <footer className="app-footer"><span>© 2026 Katalysa</span><span>Made for the people who make school happen <b>♥</b></span><span className="footer-demo">Demo data · Not a live school account</span></footer>
      </main>
    </div>
    {role === "parent" && <nav className="parent-tabs">{parentNavigation.map(item=><button key={item.path} className={screen===item.path?"active":""} onClick={()=>go(`/parent${item.path?`/${item.path}`:""}`)}>{item.icon}<span>{item.label}</span></button>)}</nav>}
    {modal && <div className="modal-layer" onMouseDown={event=>{if(event.target===event.currentTarget)closeModal();}}>{showModalContent()}</div>}
    {toastState && <div className="toast" role="status"><span className="toast-icon"><Check size={15}/></span><span><strong>{toastState.title}</strong><small>{toastState.detail}</small></span><button aria-label="Dismiss" onClick={()=>setToastState(null)}><X size={15}/></button></div>}
  </div>;
}

const adminLabels:Record<string,string>={home:"Overview","school-setup":"School setup",students:"Students",teachers:"Teachers",classes:"Classes & terms",fees:"Fees & payments",results:"Results",transcripts:"Transcripts",announcements:"Announcements",parents:"Parents",settings:"School settings",subscription:"Subscription"};
const teacherLabels:Record<string,string>={home:"Home",classes:"My classes","score-entry":"Score entry",announcements:"Announcements"};
const parentLabels:Record<string,string>={home:"Home",results:"Results",fees:"Fees",announcements:"Announcements",transcript:"Transcript",profile:"My profile"};
const adminNavigation=[
  {label:"Overview",path:"",icon:<LayoutDashboard size={17}/>},
  {label:"Students",path:"students",icon:<Users size={17}/>,count:"48"},
  {label:"Teachers",path:"teachers",icon:<GraduationCap size={17}/>},
  {label:"Classes & terms",path:"classes",icon:<CalendarDays size={17}/>},
  {label:"School setup",path:"school-setup",icon:<Building2 size={17}/>},
  {label:"Fees & payments",path:"fees",icon:<Wallet size={17}/>},
  {label:"Results",path:"results",icon:<FileCheck2 size={17}/>},
  {label:"Transcripts",path:"transcripts",icon:<FileText size={17}/>},
  {label:"Announcements",path:"announcements",icon:<MessageSquare size={17}/>},
  {label:"Parents",path:"parents",icon:<UserRound size={17}/>},
  {label:"School settings",path:"settings",icon:<Settings size={17}/>},
  {label:"Subscription",path:"subscription",icon:<CreditCard size={17}/>},
];
const parentNavigation=[
  {label:"Home",path:"",icon:<Home size={19}/>},
  {label:"Results",path:"results",icon:<FileCheck2 size={19}/>},
  {label:"Fees",path:"fees",icon:<Wallet size={19}/>},
  {label:"News",path:"announcements",icon:<MessageSquare size={19}/>},
  {label:"Transcript",path:"transcript",icon:<FileText size={19}/>},
];

function NavItem({item,active,onClick}:{item:{label:string;icon:ReactNode;count?:string};active:boolean;onClick:()=>void}){return <button className={`nav-item ${active?"active":""}`} onClick={onClick}>{item.icon}<span>{item.label}</span>{item.count&&<small>{item.count}</small>}</button>;}
function Avatar({name,colour="blue"}:{name:string;colour?:string}){return <span className={`avatar avatar-${colour}`}>{initials(name)}</span>;}
function Status({value}:{value:string}){const normalized=value.toLowerCase().replaceAll(" ","-");return <span className={`status status-${normalized}`}><i/>{value}</span>;}
function UserMenu({name,role,onProfile,onLogout}:{name:string;role:string;onProfile:()=>void;onLogout:()=>void}){return <div className="user-menu"><Avatar name={name} colour="gold"/><span><strong>{name}</strong><small>{role}</small></span><div className="user-actions"><button aria-label="Profile" onClick={onProfile}><Settings size={14}/></button><button aria-label="Log out" onClick={onLogout}><LogOut size={14}/></button></div></div>;}
function PageTitle({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:ReactNode}){return <div className="page-title"><div>{eyebrow&&<p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description&&<p className="page-description">{description}</p>}</div>{action&&<div className="title-action">{action}</div>}</div>;}
function Button({children,onClick,variant="primary",small=false,disabled=false,type}:{children:ReactNode;onClick?:()=>void;variant?:"primary"|"outline"|"soft"|"danger"|"ghost";small?:boolean;disabled?:boolean;type?:"button"|"submit"}){return <button type={type??(onClick?"button":"submit")} onClick={onClick} disabled={disabled} className={`button button-${variant} ${small?"button-small":""}`}>{children}</button>;}
function MetricCard({label,value,detail,icon,tone="navy",trend}:{label:string;value:string;detail?:string;icon:ReactNode;tone?:string;trend?:string}){return <article className="metric-card"><div className="metric-head"><span>{label}</span><span className={`metric-icon icon-${tone}`}>{icon}</span></div><strong className="metric-number">{value}</strong><div className="metric-detail">{trend&&<b>{trend}</b>}{detail}</div></article>;}
function Panel({title,subtitle,action,children,className=""}:{title:string;subtitle?:string;action?:ReactNode;children:ReactNode;className?:string}){return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>;}
function Table({headers,children}:{headers:string[];children:ReactNode}){return <div className="table-wrap"><table><thead><tr>{headers.map(header=><th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>;}
function Empty({title,detail,action,onAction}:{title:string;detail?:string;action?:string;onAction?:()=>void}){return <div className="empty-state"><span className="empty-art"><Search size={20}/></span><strong>{title}</strong>{detail&&<p>{detail}</p>}{action&&<Button small onClick={onAction}><Plus size={14}/>{action}</Button>}</div>;}
function SearchField({value,onChange,placeholder="Search..."}:{value:string;onChange:(v:string)=>void;placeholder?:string}){return <label className="search-field"><Search size={16}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>{value&&<button type="button" onClick={()=>onChange("")} aria-label="Clear search"><X size={14}/></button>}</label>;}
function FilterTabs({items,value,onChange}:{items:{key:string;label:string}[];value:string;onChange:(key:string)=>void}){return <div className="filter-tabs">{items.map(item=><button key={item.key} onClick={()=>onChange(item.key)} className={value===item.key?"selected":""}>{item.label}</button>)}</div>;}
function Field(label:string,name:string,placeholder:string,required=false,type="text",defaultValue=""){return <label>{label}{type==="password"?<PasswordInput name={name} placeholder={placeholder} required={required} defaultValue={defaultValue}/>:<input name={name} type={type} placeholder={placeholder} required={required} defaultValue={defaultValue}/>}</label>;}
function PasswordInput({name,value,onChange,placeholder,required=false,defaultValue="",autoComplete,minLength}:{name?:string;value?:string;onChange?:(value:string)=>void;placeholder?:string;required?:boolean;defaultValue?:string;autoComplete?:string;minLength?:number}){const [visible,setVisible]=useState(false);return <span className="password-input"><input name={name} type={visible?"text":"password"} value={value} onChange={event=>onChange?.(event.target.value)} placeholder={placeholder} required={required} defaultValue={value===undefined?defaultValue:undefined} autoComplete={autoComplete} minLength={minLength}/><button type="button" onClick={()=>setVisible(!visible)} aria-label={visible?"Hide password":"Show password"} aria-pressed={visible}>{visible?<EyeOff size={15}/>:<Eye size={15}/>}</button></span>;}
function KatalysaLogo({inverse=false,className=""}:{inverse?:boolean;className?:string}){return <span className={`brand-mark brand-logo ${inverse?"brand-logo-inverse":""} ${className}`}><Image src="/katalysa-logo.png" alt="" width={26} height={26}/></span>;}

function Modal({title,onClose,onSubmit,submit,children,showSubmit=true}:{title:string;onClose:()=>void;onSubmit:(event:FormEvent<HTMLFormElement>)=>void;submit:string;children:ReactNode;showSubmit?:boolean}){return <section className="modal-card" role="dialog" aria-modal="true" aria-label={title}><header className="modal-header"><div><KatalysaLogo inverse className="modal-mark"/><div><h2>{title}</h2><small>Bloomfield Academy · Demo</small></div></div><button className="icon-action" onClick={onClose} aria-label="Close dialog"><X size={18}/></button></header><form onSubmit={onSubmit}><div className="modal-body">{children}</div>{showSubmit&&<footer className="modal-footer"><Button variant="outline" onClick={onClose}>Cancel</Button><Button>{submit}<ArrowRight size={15}/></Button></footer>}</form></section>;}

function LoginScreen({onLogin,onRegister,schoolSubdomain="",mode=null}:{onLogin:(role:Role,name?:string,school?:string)=>void;onRegister?:()=>void;schoolSubdomain?:string;mode?:"staff"|"parent"|null}) {
  const [selectedMode,setSelectedMode]=useState<"staff"|"parent"|null>(mode);
  const [staffRole,setStaffRole]=useState<"admin"|"teacher">("admin");
  const [identifier,setIdentifier]=useState("");
  const [password,setPassword]=useState("");
  const [error,setError]=useState("");
  const [choosingSchool,setChoosingSchool]=useState(false);
  const [selectedSchool,setSelectedSchool]=useState("Bloomfield Academy");
  const isMultiSchoolDemo=identifier.trim().toLowerCase()==="multi@demo.katalysa.ng";
  const schoolDisplay=schoolSubdomain==="brightstars"?"Bright Stars Academy":schoolSubdomain==="bloomfield"?"Bloomfield Academy":schoolSubdomain?schoolSubdomain.split("-").map(part=>part.charAt(0).toUpperCase()+part.slice(1)).join(" "):"";
  const finishSignIn=(school=schoolDisplay||"Bloomfield Academy")=>onLogin(selectedMode==="parent"?"parent":staffRole,selectedMode==="parent"?"Mrs Okafor":staffRole==="teacher"?"Adebayo Okafor":"Amara Okafor",school);
  const submitCredentials=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setError("");if(isMultiSchoolDemo&&!schoolSubdomain){setChoosingSchool(true);return;}finishSignIn();};
  const brand=<div className="auth-brand"><KatalysaLogo/><strong>Katalysa<span className="brand-period">.</span></strong></div>;
  const portalHeading=selectedMode==="parent"?"PARENT PORTAL":staffRole==="teacher"?"STAFF PORTAL":"ADMINISTRATOR PORTAL";
  const portalTitle=selectedMode==="parent"?"Welcome back.":staffRole==="teacher"?"Staff sign in.":"Administrator sign in.";
  return <div className="auth-page"><div className="auth-atmosphere"/>{brand}<div className="auth-card login-card">
    <div className="school-lockup"><span className="school-monogram large">{schoolDisplay?schoolDisplay.charAt(0):<Building2 size={21}/>}</span><div><strong>{schoolDisplay||"Katalysa central portal"}</strong><small>{schoolSubdomain?"School sign in · katalysa.ng":"Choose a portal to continue"}</small></div></div>
    {!selectedMode&&!choosingSchool ? <>
      <div className="auth-title"><span className="eyebrow">SECURE SCHOOL ACCESS</span><h1>Who would you like to sign in as?</h1><p>Select the portal for your account.</p></div>
      <div className="portal-options">
        <button onClick={()=>{setStaffRole("admin");setSelectedMode("staff");}}><span className="role-avatar admin"><Building2 size={18}/></span><span><strong>School administrator</strong></span></button>
        <button onClick={()=>{setStaffRole("teacher");setSelectedMode("staff");}}><span className="role-avatar admin"><GraduationCap size={18}/></span><span><strong>Staff / teacher</strong></span></button>
        <button onClick={()=>setSelectedMode("parent")}><span className="role-avatar parent"><Users size={18}/></span><span><strong>Parent</strong></span></button>
      </div>
      {onRegister&&<p className="auth-register">New school? <button onClick={onRegister}>Register your school <ArrowRight size={13}/></button></p>}
    </> : choosingSchool ? <>
      <div className="auth-title"><span className="eyebrow">SCHOOL SELECTION</span><h1>Choose a school.</h1><p>This demo account has access to more than one school.</p></div>
      <form className="auth-form" onSubmit={event=>{event.preventDefault();finishSignIn(selectedSchool);}}><label>School<select value={selectedSchool} onChange={event=>setSelectedSchool(event.target.value)}><option>Bloomfield Academy</option><option>Cedar Grove College</option></select></label><button className="button button-primary auth-submit">Continue to school <ArrowRight size={16}/></button></form>
    </> : <>
      <div className="auth-title"><span className="eyebrow">{portalHeading}</span><h1>{portalTitle}</h1><p>{schoolDisplay?`Enter your details for ${schoolDisplay}, or continue directly in this prototype.`:"Your details are optional in this prototype."}</p></div>
      <form noValidate onSubmit={submitCredentials} className="auth-form">
        <label>Email or phone number <small className="field-optional">Optional</small><input type="text" value={identifier} onChange={event=>setIdentifier(event.target.value)} placeholder="name@school.edu.ng or 08012345678" autoComplete="username"/></label>
        <label>Password <small className="field-optional">Optional</small><PasswordInput value={password} onChange={setPassword} placeholder="Enter your password" autoComplete="current-password"/></label>
        {error&&<p className="field-error">{error}</p>}
        <button className="button button-primary auth-submit">Sign in <ArrowRight size={16}/></button>
        <button type="button" className="forgot-link" onClick={()=>setError("Password recovery is not connected in this prototype. Contact your school administrator.")}>Forgot password?</button>
      </form>
      <p className="auth-foot">Demo only: you can sign in without entering any details. {selectedMode==="parent"?"Parent access is provided by the school; self-registration is unavailable.":"Role and school permissions require backend verification."}</p>
      <div className="login-switch"><button onClick={()=>{setSelectedMode(selectedMode==="parent"?"staff":"parent");setError("");}}>Switch to {selectedMode==="parent"?"staff":"parent"} sign in</button>{!schoolSubdomain&&<button onClick={()=>{setSelectedMode(null);setChoosingSchool(false);setError("");}}>All sign-in options</button>}</div>
    </>}
  </div><p className="auth-foot"><LockKeyhole size={12}/> Katalysa sign-in prototype <span>·</span> No credentials are sent to a server</p></div>;
}
function RegisterScreen({schoolName,setSchoolName,onRegister}:{schoolName:string;setSchoolName:(v:string)=>void;onRegister:(name:string,adminName:string)=>void}){
  const [subdomain,setSubdomain]=useState("");const [error,setError]=useState("");
  return <div className="auth-page register-page"><div className="auth-brand"><KatalysaLogo/><strong>Katalysa<span className="brand-period">.</span></strong></div><div className="register-card"><button className="back-link" onClick={()=>history.back()}><ArrowLeft size={15}/> Back to Katalysa</button><div className="auth-title"><span className="eyebrow">GET YOUR SCHOOL STARTED</span><h1>Bring your school into focus.</h1><p>Set up your school workspace in a few simple steps.</p></div><form className="registration-form" onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);const school=String(form.get("school")||"").trim();const administrator=String(form.get("adminName")||"").trim();const password=String(form.get("password")||"");const confirmation=String(form.get("confirmPassword")||"");if(!school||!administrator){setError("Enter your school name and administrator name.");return;}if(password.length<8||password!==confirmation){setError("Use a password of at least 8 characters and enter it the same way twice.");return;}setSchoolName(school);onRegister(school,administrator);}}><h2>School information</h2><div className="form-grid">{Field("School name","school","e.g. Bloomfield Academy",true,"text",schoolName)}{Field("Address","address","Street and number")}{Field("State","state","Lagos")}{Field("Local government area","lga","Ikeja")}<label>School type<select name="schoolType"><option>Both</option><option>Primary</option><option>Secondary</option></select></label><label>School web address<div className="subdomain-field"><input value={subdomain} onChange={e=>setSubdomain(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,""))} placeholder="your-school"/><span>.katalysa.ng</span></div></label></div><h2>Administrator account</h2><div className="form-grid">{Field("Full name","adminName","Your name",true)}{Field("Phone number","phone","0800 000 0000",true,"tel")}{Field("Email (optional)","email","you@example.com",false,"email")}{Field("Password","password","At least 8 characters",true,"password")}{Field("Confirm password","confirmPassword","Enter password again",true,"password")}</div>{subdomain&&<p className="subdomain-preview"><CheckCircle2 size={14}/>{subdomain}.katalysa.ng is shown as a preview only</p>}{error&&<p className="field-error">{error}</p>}<button className="button button-primary auth-submit">Register school <ArrowRight size={16}/></button></form><p className="auth-foot">Demo registration only · No account or tenant is created</p></div></div>;
}

function ChangePasswordScreen({onComplete,onSkip}:{onComplete:()=>void;onSkip:()=>void}){const [error,setError]=useState("");return <div className="auth-page"><div className="auth-brand"><KatalysaLogo/><strong>Katalysa<span className="brand-period">.</span></strong></div><div className="auth-card change-card"><span className="auth-icon-large"><KeyRound size={22}/></span><div className="auth-title"><span className="eyebrow">ONE MORE STEP</span><h1>Choose a new password.</h1><p>Your school administrator created your account. Change your temporary password to continue.</p></div><form className="auth-form" onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);if(form.get("new")!==form.get("confirm")){setError("The new password and confirmation do not match.");return;}setError("");onComplete();}}><label>Current password<PasswordInput name="old" required autoComplete="current-password"/></label><label>New password<PasswordInput name="new" required minLength={8} autoComplete="new-password"/></label><label>Confirm new password<PasswordInput name="confirm" required minLength={8} autoComplete="new-password"/></label>{error&&<p className="field-error">{error}</p>}<button className="button button-primary auth-submit">Update password <ArrowRight size={16}/></button><button type="button" className="forgot-link" onClick={onSkip}>Continue to dashboard</button></form><p className="auth-foot">Demo mode · Password changes are simulated</p></div></div>;}

function DemoCheckout({reference,onComplete,onCancel}:{reference:string;onComplete:(r:string)=>void;onCancel:()=>void}){const [method,setMethod]=useState("Card");const [amount,setAmount]=useState(15000);useEffect(()=>{try{const raw=window.localStorage.getItem(`katalysa-demo-payment-${reference}`);if(raw)setAmount(Number(JSON.parse(raw).total)||15000);}catch{}},[reference]);return <div className="checkout-page"><header className="checkout-header"><KatalysaLogo/><strong>Katalysa<span className="brand-period">.</span></strong><span className="checkout-secure"><LockKeyhole size={14}/> DEMO CHECKOUT</span></header><main className="checkout-card"><button className="back-link" onClick={onCancel}><ArrowLeft size={15}/> Return to Katalysa</button><div className="checkout-school"><span className="school-monogram">B</span><span>Bloomfield Academy<small>Payment simulation</small></span></div><span className="eyebrow">SIMULATED PAYMENT</span><h1>{naira(amount)}</h1><p className="checkout-sub">This screen represents the hand-off to hosted Paystack checkout. It is a local simulation: no card fields, bank transfer, USSD, or live payment is available.</p><div className="checkout-ref"><span>Reference</span><strong>{reference}</strong></div><div className="checkout-methods">{["Card","Bank transfer","USSD"].map(item=><button className={method===item?"selected":""} key={item} onClick={()=>setMethod(item)}>{item}</button>)}</div><Button onClick={()=>onComplete(reference)}><CheckCircle2 size={16}/> Simulate successful payment</Button><button className="checkout-fail" onClick={onCancel}>Cancel this demo payment</button><p className="checkout-disclaimer"><ShieldCheck size={14}/> Demo payment only. No provider is contacted and no money moves.</p></main></div>;}

function PaymentCallback({result,goFees,goTranscript}:{result:{status:string;purpose:string;total_amount?:number}|null;goFees:()=>void;goTranscript:()=>void}){return <div className="callback-page"><div className="auth-brand"><KatalysaLogo/><strong>Katalysa<span className="brand-period">.</span></strong></div><div className="callback-card"><span className={`callback-icon ${result?.status==="success"?"success":""}`}>{result?.status==="success"?<CheckCircle2 size={28}/>:<Activity size={25}/>}</span><span className="eyebrow">PAYMENT CALLBACK · DEMO</span><h1>{!result?"Verifying your demo payment…":result.status==="success"?result.purpose==="transcript"?"Transcript unlocked":"Payment successful":"Payment not completed"}</h1><p>{!result?"Checking the simulated transaction reference.":result.status==="success"?`A sample payment of ${naira(result.total_amount||0)} was confirmed locally. No payment provider was contacted.`:"The demonstration payment could not be verified."}</p>{result?.status==="success"&&<Button onClick={result.purpose==="transcript"?goTranscript:goFees}>Continue to {result.purpose==="transcript"?"transcript":"fees"} <ArrowRight size={15}/></Button>}</div></div>;}

function AdminHome({students,fees,onNewStudent,onLogPayment,onLevelFee,onNewAnnouncement,onNavigate}:{students:Student[];fees:Fee[];onNewStudent:()=>void;onLogPayment:()=>void;onLevelFee:()=>void;onNewAnnouncement:()=>void;onNavigate:(p:string)=>void}) {
  const recentStudents = [
    { initials: "ZA", name: "Zara Adeyemi", className: "JSS 2", guardian: "Tunde Adeyemi", colour: "violet" },
    { initials: "CO", name: "Chidera Okonkwo", className: "SSS 1", guardian: "Ngozi Okonkwo", colour: "peach" },
    { initials: "MB", name: "Mariam Bello", className: "JSS 1", guardian: "Ibrahim Bello", colour: "mint" },
    { initials: "DE", name: "Daniel Eze", className: "SSS 2", guardian: "Chika Eze", colour: "blue" },
  ];
  const activities = [
    { icon: <Wallet size={16}/>, tone: "mint", title: "School fees payment recorded", detail: "₦185,000 from Zara Adeyemi", time: "Today, 10:32 AM" },
    { icon: <Users size={16}/>, tone: "lavender", title: "New student enrolled", detail: "Olawuseun Ojo · Primary 4", time: "Today, 9:15 AM" },
    { icon: <ClipboardList size={16}/>, tone: "peach", title: "Results submitted", detail: "JSS 2 · Basic Science", time: "Yesterday, 3:48 PM" },
    { icon: <Bell size={16}/>, tone: "blue", title: "Announcement published", detail: "Mid-term break begins Friday", time: "Yesterday, 11:05 AM" },
  ];
  return <>
    <div className="admin-dashboard-welcome">
      <div>
        <p className="eyebrow">SUNDAY, 18 OCTOBER 2026</p>
        <h1>Good morning, Amara <span aria-hidden="true">☀️</span></h1>
        <p>Here’s what’s happening at Bloomfield Academy today.</p>
      </div>
      <Button onClick={onNewStudent}><Plus size={16}/> Add student</Button>
    </div>
    <div className="metric-grid">
      <MetricCard label="Total students" value="248" detail="compared to last term" icon={<Users size={17}/>} tone="navy" trend="↗ 12%"/>
      <MetricCard label="Teaching staff" value="32" detail="this academic year" icon={<GraduationCap size={17}/>} tone="green" trend="↗ 2 new"/>
      <MetricCard label="Fees collected" value="₦18.4m" detail="of the term target" icon={<Landmark size={17}/>} tone="orange" trend="77%"/>
      <MetricCard label="Outstanding" value="₦5.6m" detail="62 students with a balance" icon={<Wallet size={17}/>} tone="blue" trend="23%"/>
    </div>
    <div className="quick-actions">
      <span className="quick-label">QUICK ACTIONS</span>
      <Button variant="outline" onClick={onLogPayment}><Plus size={16}/> Log payment</Button>
      <Button variant="outline" onClick={onLevelFee}><Wallet size={16}/> Set level fees</Button>
      <Button variant="outline" onClick={onNewStudent}><UserRound size={16}/> Register student</Button>
      <Button variant="outline" onClick={onNewAnnouncement}><Bell size={16}/> New announcement</Button>
    </div>
    <Panel title="Recent activity" subtitle="Latest updates from your school" className="dashboard-activity-panel">
      <div className="dashboard-activity-grid">
        {activities.map((activity) => <article className="dashboard-activity-item" key={activity.title}>
          <span className={`dashboard-activity-icon ${activity.tone}`}>{activity.icon}</span>
          <span className="dashboard-activity-copy"><strong>{activity.title}</strong><span>{activity.detail}</span><small>{activity.time}</small></span>
        </article>)}
      </div>
    </Panel>
    <div className="dashboard-columns dashboard-lower-row">
      <Panel title="Recently added students" subtitle="The latest additions to your school" action={<button className="text-button" onClick={()=>onNavigate("/admin/students")}>View all students <ArrowRight size={14}/></button>}>
        <Table headers={["STUDENT","CLASS","GUARDIAN","STATUS"]}>
          {recentStudents.map((student) => <tr key={student.name}>
            <td><div className="student-cell"><Avatar name={student.name} colour={student.colour}/><span>{student.name}</span></div></td>
            <td>{student.className}</td><td>{student.guardian}</td><td><Status value="Active"/></td>
          </tr>)}
        </Table>
      </Panel>
      <Panel title="Fee collection" subtitle="Second term · 2025/2026" action={<button className="text-button" onClick={()=>onNavigate("/admin/fees")}>Details <ArrowRight size={14}/></button>} className="dashboard-fee">
        <div className="collection-number"><strong>₦18.4m</strong><span>of ₦24m</span></div>
        <div className="progress-track"><span style={{width:"77%"}}/></div>
        <div className="collection-meta"><span>77% collected</span><span>23% outstanding</span></div>
        <div className="collection-divider"/>
        <div className="collection-foot collection-foot-two"><span>Paid in full<strong>186 students</strong></span><span>Outstanding<strong>62 students</strong></span></div>
      </Panel>
    </div>
    <div className="dashboard-footnote"><ShieldCheck size={15}/> Dashboard figures and activity are fictional demonstration data. Actions are simulated in this prototype.</div>
  </>;
}

function SchoolSetup({done,onToggle,onNavigate}:{done:boolean[];onToggle:(i:number)=>void;onNavigate:(p:string)=>void}){const setup=[{title:"Upload school logo and stamp",detail:"Add your school branding to reports and receipts.",path:"/admin/settings",icon:<Building2/>},{title:"Create academic session",detail:"Set the academic year for your school.",path:"/admin/classes",icon:<CalendarDays/>},{title:"Create terms and set active term",detail:"Define the term dates and select the current term.",path:"/admin/classes",icon:<CalendarDays/>},{title:"Create classes",detail:"Add the classes currently running in your school.",path:"/admin/classes",icon:<Users/>},{title:"Create subjects",detail:"Choose subjects taught across your classes.",path:"/admin/classes",icon:<BookOpen/>},{title:"Configure score components",detail:"Set CA, exam and other score maximums.",path:"/admin/results",icon:<ClipboardList/>},{title:"Configure grading scale",detail:"Set the mark ranges and remarks for your reports.",path:"/admin/results",icon:<FileCheck2/>}];return <><PageTitle eyebrow="LET’S GET YOUR SCHOOL READY" title="School setup" description="A short checklist to prepare your workspace for the term."/><div className="setup-summary"><span className="setup-summary-icon"><ShieldCheck size={20}/></span><div><strong>{done.filter(Boolean).length} of 7 essentials complete</strong><p>Complete your school setup so families and teachers have a smooth start.</p></div><div className="setup-big-progress"><strong>{Math.round(done.filter(Boolean).length/7*100)}%</strong><div className="progress-track"><span style={{width:`${done.filter(Boolean).length/7*100}%`}}/></div></div></div><div className="setup-list">{setup.map((item,i)=><article key={item.title} className={`setup-row ${done[i]?"done":""}`}><button className={`setup-check ${done[i]?"checked":""}`} aria-label={`Mark ${item.title}`} onClick={()=>onToggle(i)}>{done[i]&&<Check size={15}/>}</button><span className="setup-icon">{item.icon}</span><div className="setup-copy"><strong>{item.title}</strong><small>{item.detail}</small></div><button className="text-button" onClick={()=>onNavigate(item.path)}>{done[i]?"Review":"Set up"}<ArrowRight size={14}/></button></article>)}</div><p className="note setup-note">Checklist progress is local to this prototype. Upload controls and setup APIs are simulated.</p></>;}

function StudentsScreen({students,filter,setFilter,search,setSearch,onAdd,onOpen,onExport}:{students:Student[];filter:StudentStatus|"all";setFilter:(v:StudentStatus|"all")=>void;search:string;setSearch:(v:string)=>void;onAdd:()=>void;onOpen:(s:Student)=>void;onExport:()=>void}){const tabs=[{key:"all",label:"All students"},{key:"active",label:"Active"},{key:"graduated",label:"Graduated"},{key:"withdrawn",label:"Withdrawn"},{key:"inactive",label:"Inactive"}];return <><PageTitle eyebrow="PEOPLE DIRECTORY" title="Students" description="Manage enrolment, family contacts and student status." action={<Button onClick={onAdd}><Plus size={16}/> Register student</Button>}/><div className="list-summary"><div><strong>48</strong><span>Students in school</span></div><div><strong>{students.filter(s=>s.status==="active").length}</strong><span>Shown in this view</span></div><div><strong>{new Set(students.map(s=>s.className)).size}</strong><span>Classes represented</span></div><button className="text-button" onClick={onExport}><Download size={15}/> Export list</button></div><div className="filter-bar"><FilterTabs items={tabs} value={filter} onChange={key=>setFilter(key as StudentStatus|"all")}/><SearchField value={search} onChange={setSearch} placeholder="Search name, admission no. or parent"/></div><div className="panel no-pad"><Table headers={["STUDENT","ADMISSION NO.","CLASS","PARENT / GUARDIAN","STATUS","AVERAGE",""]}>{students.length?students.map(student=><tr key={student.id} className="clickable-row" onClick={()=>onOpen(student)}><td><div className="student-cell"><Avatar name={student.name} colour={student.colour}/><span>{student.name}<small>{student.sex} · DOB {student.dob}</small></span></div></td><td className="mono-cell">{student.admission}</td><td>{student.className}</td><td><span className="parent-cell">{student.parent}<small>{student.phone}</small></span></td><td><Status value={student.status}/></td><td><span className="average-pill">{student.average}%</span></td><td><button className="icon-action" aria-label={`View ${student.name}`} onClick={e=>{e.stopPropagation();onOpen(student);}}><ChevronRight size={17}/></button></td></tr>):<tr><td colSpan={7}><Empty title="No students found" detail="Try a different search or status filter." action="Register student" onAction={onAdd}/></td></tr>}</Table><div className="table-footer"><span>Showing {students.length} sample student records · 48 total</span><div className="pager"><button disabled><ChevronLeft size={14}/></button><button className="current">1</button><button onClick={()=>{}}>2</button><button onClick={()=>{}}>3</button><button><ChevronRight size={14}/></button></div></div></div></>;}

function TeachersScreen({teachers,filter,setFilter,search,setSearch,onAdd,onOpen}:{teachers:Teacher[];filter:TeacherStatus;setFilter:(v:TeacherStatus)=>void;search:string;setSearch:(v:string)=>void;onAdd:()=>void;onOpen:(t:Teacher)=>void}){const count=teachers.length;return <><PageTitle eyebrow="PEOPLE DIRECTORY" title="Teachers" description="Manage teacher accounts, status and class assignments." action={<Button onClick={onAdd}><Plus size={16}/> Add teacher</Button>}/><div className="list-summary"><div><strong>32</strong><span>Total teacher accounts</span></div><div><strong>30</strong><span>Active</span></div><div><strong>2</strong><span>Inactive</span></div><div className="summary-spacer"/><SearchField value={search} onChange={setSearch} placeholder="Search teachers"/></div><div className="filter-bar"><FilterTabs items={[{key:"active",label:"Active teachers"},{key:"inactive",label:"Inactive teachers"}]} value={filter} onChange={key=>setFilter(key as TeacherStatus)}/><span className="subtle">{count} sample records</span></div><div className="panel no-pad"><Table headers={["TEACHER","PHONE","EMAIL","ASSIGNMENTS","STATUS","DATE LEFT",""]}>{teachers.length?teachers.map(teacher=><tr className="clickable-row" key={teacher.id} onClick={()=>onOpen(teacher)}><td><div className="student-cell"><Avatar name={teacher.name} colour="violet"/><span>{teacher.name}<small>Staff member · Bloomfield Academy</small></span></div></td><td>{teacher.phone}</td><td className="muted-cell">{teacher.email}</td><td><span className="count-pill">{teacher.assignments.length} classes</span></td><td><Status value={teacher.status}/></td><td className="muted-cell">{teacher.dateLeft||"—"}</td><td><button className="icon-action" onClick={e=>{e.stopPropagation();onOpen(teacher);}}><ChevronRight size={17}/></button></td></tr>):<tr><td colSpan={7}><Empty title={`No ${filter} teachers`} detail="Add a teacher or switch the status filter." action="Add teacher" onAction={onAdd}/></td></tr>}</Table><div className="table-footer"><span>Showing sample teachers · 32 total accounts</span><span className="subtle">Account status changes are simulated</span></div></div></>;}

function ClassesScreen({groups,published,onAdd,onEditTerms}:{groups:ClassGroup[];published:boolean;onAdd:()=>void;onEditTerms:()=>void}){const [tab,setTab]=useState("Classes");const tabList=["Classes","Sessions & terms","Subjects","Score components","Grading scale"];return <><PageTitle eyebrow="ACADEMIC SETUP" title="Classes & terms" description="Organise your school calendar, classes and the building blocks of assessment." action={<Button onClick={tab==="Classes"?onAdd:onEditTerms}><Plus size={16}/> {tab==="Classes"?"Add class":"Add item"}</Button>}/><div className="panel setup-panel"><div className="panel-heading"><div><h2>{activeTerm}</h2><p>Active term · Academic session 2024/2025</p></div><span className="active-chip"><i/>Active</span></div><div className="term-dates"><div><small>TERM BEGINS</small><strong>23 Sep 2024</strong></div><div><small>TERM ENDS</small><strong>13 Dec 2024</strong></div><div><small>RESULTS STATUS</small><strong>{published?"Published":"In progress"}</strong></div><Button variant="outline" small onClick={onEditTerms}><Pencil size={14}/> Edit calendar</Button></div></div><div className="tab-row">{tabList.map(item=><button key={item} onClick={()=>setTab(item)} className={tab===item?"active":""}>{item}</button>)}</div>{tab==="Classes"?<div className="class-grid">{groups.map(item=><article className="class-card" key={item.name}><div className="class-card-head"><span className="class-symbol"><BookOpen size={17}/></span><span className="count-pill">{item.students} students</span></div><strong>{item.name}</strong><small>{item.level}</small><div className="class-teacher"><Avatar name={item.teacher} colour="mint"/><span>Class teacher<strong>{item.teacher}</strong></span><button className="icon-action"><MoreHorizontal size={17}/></button></div></article>)}</div>:<div className="panel"><div className="setup-config"><div><span className="setup-icon"><CalendarDays size={18}/></span><span><strong>{tab}</strong><small>{tab==="Sessions & terms"?"2024/2025 · First, Second and Third Term":tab==="Subjects"?"Mathematics · English · Basic Science · Social Studies":"CA1 / 20 · CA2 / 20 · Exam / 60"}</small></span></div><Button variant="outline" small onClick={onEditTerms}><Pencil size={14}/> Manage</Button></div><div className="setup-config"><div><span className="setup-icon"><CheckCircle2 size={18}/></span><span><strong>{tab==="Grading scale"?"A 75–100 · B 65–74 · C 55–64":"Current school configuration"}</strong><small>Changes here are displayed as demo interactions.</small></span></div><Button variant="ghost" small onClick={onEditTerms}>Edit <ArrowRight size={14}/></Button></div></div>}</>;}

function AdminFees({fees,filter,setFilter,search,setSearch,onLevelFee,onLogPayment,onExport}:{fees:Fee[];filter:string;setFilter:(v:string)=>void;search:string;setSearch:(v:string)=>void;onLevelFee:()=>void;onLogPayment:()=>void;onExport:()=>void}){const [tab,setTab]=useState("Fee records");return <><PageTitle eyebrow="SCHOOL FINANCES" title="Fees & payments" description="Set term fees, review balances and record family payments." action={<div className="inline-actions"><Button variant="outline" onClick={onLevelFee}><Wallet size={15}/> Set level fees</Button><Button onClick={onLogPayment}><Plus size={16}/> Log payment</Button></div>}/><div className="metric-grid"><MetricCard label="Total expected" value="₦630,000" detail="Active term · 48 students" icon={<Wallet size={17}/>} tone="navy"/><MetricCard label="Collected" value="₦330,000" detail="52% of expected fees" icon={<Landmark size={17}/>} tone="green" trend="52%"/><MetricCard label="Outstanding" value="₦300,000" detail="16 students have a balance" icon={<Activity size={17}/>} tone="orange"/><MetricCard label="Fully paid" value="32" detail="Students with no balance" icon={<CheckCircle2 size={17}/>} tone="blue"/></div><div className="tab-row"><button onClick={()=>setTab("Fee records")} className={tab==="Fee records"?"active":""}>Fee records</button><button onClick={()=>setTab("Payment history")} className={tab==="Payment history"?"active":""}>Payment history</button><button onClick={()=>setTab("Fee setup")} className={tab==="Fee setup"?"active":""}>Fee setup</button></div>{tab==="Fee setup"?<div className="panel"><div className="panel-heading"><div><h2>Fees by class level</h2><p>Set an academic fee and processing allowance for a whole level.</p></div><Button onClick={onLevelFee}><Plus size={15}/> Set level fee</Button></div><Table headers={["LEVEL","TERM","ACADEMIC FEE","TOTAL PAYABLE","AFFECTED STUDENTS",""]}>{levels.slice(0,4).map(level=><tr key={level}><td><strong>{level}</strong></td><td>{activeTerm}</td><td>₦50,000</td><td className="strong-cell">₦55,000</td><td>8 students</td><td><button className="text-button" onClick={onLevelFee}>Edit</button></td></tr>)}</Table><p className="note">The processing allowance is included in total payable. Never show it as a separate parent-facing charge.</p></div>:<><div className="filter-bar"><FilterTabs items={[{key:"all",label:"All records"},{key:"outstanding",label:"Outstanding"},{key:"paid",label:"Paid"},{key:"overpaid",label:"Overpaid"}]} value={filter} onChange={setFilter}/><SearchField value={search} onChange={setSearch} placeholder="Find a student"/></div><div className="panel no-pad"><div className="table-toolbar"><div><strong>{tab}</strong><small>{activeTerm} · {fees.length} sample records</small></div><Button variant="outline" small onClick={onExport}><Download size={14}/> Export CSV</Button></div><Table headers={["STUDENT","TOTAL PAYABLE","PAID","BALANCE","STATUS","LAST PAYMENT",""]}>{fees.length?fees.map(fee=><tr key={fee.id}><td><div className="student-cell"><Avatar name={fee.student}/><span>{fee.student}<small>{fee.className}</small></span></div></td><td className="strong-cell">{naira(fee.totalPayable)}</td><td>{naira(fee.paid)}</td><td className={fee.balance<0?"positive-cell":fee.balance>0?"warning-text":""}>{fee.balance<0?`−${naira(-fee.balance)}`:naira(fee.balance)}</td><td><Status value={fee.status}/></td><td className="muted-cell">{fee.paid>0?"Today":"—"}</td><td><button className="text-button" onClick={onLogPayment}>Log</button></td></tr>):<tr><td colSpan={7}><Empty title="No fee records here" detail="Try another status filter or set fees for a level." action="Set level fees" onAction={onLevelFee}/></td></tr>}</Table><div className="table-footer"><span>Showing {fees.length} sample fee records. Values are fictional.</span><span>{activeTerm}</span></div></div></>}{tab==="Payment history"&&<div className="note">Payment history is summarized per student in this mock view. Log a payment to update a sample balance.</div>}</>;}

function AdminResults({assignments,published,onComplete,onPublish,onDownload,onSaveScores}:{assignments:Assignment[];published:boolean;onComplete:()=>void;onPublish:()=>void;onDownload:()=>void;onSaveScores:()=>void}){const [tab,setTab]=useState("Publish results");const [subject,setSubject]=useState("Mathematics · JSS 1");const allComplete=assignments.every(a=>a.complete>=a.students);return <><PageTitle eyebrow="ACADEMIC RECORDS" title="Results" description="Track score completion, publish term results and prepare class report sheets." action={<Button variant="outline" onClick={onDownload}><Download size={15}/> Bulk download</Button>}/><div className="result-term"><span className="term-mark"><FileCheck2 size={19}/></span><div><strong>{activeTerm}</strong><small>Bloomfield Academy · Active term</small></div><span className={`status ${published?"status-paid":"status-partial"}`}><i/>{published?"Published":"In progress"}</span><button className="text-button" onClick={()=>notifySmall(onSaveScores)}>Save draft</button></div><div className="tab-row"><button className={tab==="Publish results"?"active":""} onClick={()=>setTab("Publish results")}>Publish results</button><button className={tab==="Score overview"?"active":""} onClick={()=>setTab("Score overview")}>Score overview</button><button className={tab==="Downloads"?"active":""} onClick={()=>setTab("Downloads")}>Downloads</button></div>{tab==="Publish results"?<><div className="warning-banner"><span><AlertTriangle size={18}/></span><div><strong>Publishing locks all scores and notifies parents.</strong><small>Review assignment completion before you publish the term.</small></div>{!allComplete&&<Button variant="outline" small onClick={onComplete}>Complete sample scores</Button>}</div><div className="panel no-pad"><Table headers={["CLASS","SUBJECT","COMPLETION","STATUS",""]}>{assignments.map(item=><tr key={item.id}><td><strong>{item.className}</strong></td><td>{item.subject}</td><td><div className="completion-cell"><div className="progress-track"><span style={{width:`${item.complete/item.students*100}%`}}/></div><small>{item.complete}/{item.students} complete</small></div></td><td>{item.complete===item.students?<Status value="Complete"/>:<Status value="Incomplete"/>}</td><td><button className="text-button" onClick={()=>{setSubject(`${item.subject} · ${item.className}`);setTab("Score overview");}}>Review scores <ArrowRight size={14}/></button></td></tr>)}</Table><div className="table-footer"><span>{assignments.filter(a=>a.complete===a.students).length} of {assignments.length} assignment groups complete</span><Button disabled={!allComplete||published} onClick={onPublish}><Send size={15}/>{published?"Results published":"Publish results"}</Button></div></div></>:tab==="Score overview"?<ScoreEntryMini assignments={assignments} subject={subject} onSave={onSaveScores}/>:<div className="download-grid"><button className="download-card" onClick={onDownload}><span><FileText/></span><strong>Download one result sheet</strong><small>Choose a student and term to prepare a PDF.</small><b>Prepare PDF <ArrowRight size={14}/></b></button><button className="download-card" onClick={onDownload}><span><Download/></span><strong>Download class results</strong><small>Prepare all student reports for a class as a ZIP.</small><b>Prepare ZIP <ArrowRight size={14}/></b></button></div>}<p className="note">Result publishing, parent notifications and PDF/ZIP downloads are represented locally. Nothing is sent to the school backend.</p></>;}
function notifySmall(fn:()=>void){fn();}
function ScoreEntryMini({assignments,subject,onSave}:{assignments:Assignment[];subject:string;onSave:()=>void}){return <div className="panel"><div className="panel-heading"><div><h2>Score overview</h2><p>{subject} · {activeTerm}</p></div><Button onClick={onSave}><Check size={15}/> Save score edits</Button></div><div className="score-summary"><span>Score components<strong>CA1 / 20 · CA2 / 20 · Exam / 60</strong></span><span>Sample class progress<strong>{assignments[0]?.complete}/{assignments[0]?.students} complete</strong></span><span>Pass threshold<strong>40%</strong></span></div><p className="note">Teachers enter scores in their portal. Admins review assignment progress and publish when every group is complete.</p></div>;}

function AdminTranscripts({students,onPurchase}:{students:Student[];onPurchase:()=>void}){const [query,setQuery]=useState("");const [selected,setSelected]=useState<number|null>(null);const filtered=students.filter(student=>`${student.name} ${student.admission}`.toLowerCase().includes(query.toLowerCase()));return <><PageTitle eyebrow="ACADEMIC RECORDS" title="Transcripts" description="Record a transcript purchase when a family pays the school directly."/><div className="transcript-layout"><Panel title="Record a transcript purchase" subtitle="Unlock a transcript after an admin has confirmed receipt of payment"><div className="form-grid"><label>Student<SearchField value={query} onChange={setQuery} placeholder="Search by name or admission number"/>{query&&<div className="student-options">{filtered.map(student=><button key={student.id} onClick={()=>{setSelected(student.id);setQuery(student.name);}}>{student.name}<small>{student.admission} · {student.className}</small></button>)}</div>}</label><label>Parent<select><option>Choose linked parent</option>{students.map(student=><option key={student.id}>{student.parent} · {student.name}</option>)}</select></label><label>Amount paid<input type="number" placeholder="₦5,000"/></label><label>Method<select><option>Cash</option><option>Bank transfer</option><option>POS</option></select></label><label className="full-span">Reference (optional)<input placeholder="Receipt or bank reference"/></label></div><div className="panel-actions"><Button disabled={!selected} onClick={onPurchase}><Check size={15}/> Record purchase</Button></div><p className="note">Admin-recorded purchase is simulated. The live endpoint records payment and unlocks downloads for the parent.</p></Panel><aside className="side-info"><span className="side-info-icon"><FileText size={20}/></span><h3>One purchase per student</h3><p>A transcript purchase unlocks unlimited downloads for that child. You can also set the transcript price in School settings.</p><div><small>DEMO TRANSCRIPT FEE</small><strong>₦5,000</strong></div></aside></div></>;}

function AnnouncementsScreen({announcements,onNew,onDelete,role}:{announcements:Announcement[];onNew?:()=>void;onDelete?:(id:number)=>void;role:"admin"|"teacher"|"parent"}){const [filter,setFilter]=useState("all");const visible=announcements.filter(item=>filter==="all"||item.audience===filter);return <><PageTitle eyebrow={role==="admin"?"SCHOOL COMMUNITY":"SCHOOL UPDATES"} title="Announcements" description={role==="admin"?"Share timely updates with parents, teachers or your whole school.":"Important notes and updates from Bloomfield Academy."} action={role==="admin"&&<Button onClick={onNew}><Plus size={16}/> New announcement</Button>}/>{role==="admin"&&<div className="announcement-tools"><FilterTabs value={filter} onChange={setFilter} items={[{key:"all",label:"All posts"},{key:"parents",label:"Parents"},{key:"teachers",label:"Teachers"}]}/><span className="subtle">{announcements.length} announcements</span></div>}<div className="announcement-list">{visible.length?visible.map(item=><article className="announcement-card" key={item.id}><span className="announcement-icon"><MessageSquare size={18}/></span><div className="announcement-content"><div className="announcement-heading"><h2>{item.title}</h2><time>{item.date}</time></div><p>{item.body}</p><div className="announcement-tags"><span className="audience-chip">{item.audience==="all"?"Everyone":item.audience==="parents"?"Parents only":"Teachers only"}</span>{item.sendSms&&<span className="sms-chip"><Send size={12}/> SMS requested</span>}<span className="published-chip"><i/>Published</span></div></div>{role==="admin"&&<button className="icon-action" aria-label="Remove announcement" onClick={()=>onDelete?.(item.id)}><MoreHorizontal size={17}/></button>}</article>):<div className="panel"><Empty title="No announcements yet" detail="Post a school update to get the conversation started." action="New announcement" onAction={onNew}/></div>}</div>{role==="admin"&&<p className="note">SMS delivery is not active in this prototype. All updates remain local demo content.</p>}</>;}

function ParentsScreen({students,onUpdate}:{students:Student[];onUpdate:(student:Student)=>void}){const parents=students.filter((student,index)=>students.findIndex(other=>other.phone===student.phone)===index);return <><PageTitle eyebrow="FAMILY DIRECTORY" title="Parents & guardians" description="Find a family, review linked children and update their contact details."/><div className="list-summary"><div><strong>{parents.length}</strong><span>Sample family accounts</span></div><div><strong>48</strong><span>Students linked</span></div><div className="summary-spacer"/><SearchField value="" onChange={()=>{}} placeholder="Search parent name or phone"/></div><div className="panel no-pad"><Table headers={["PARENT / GUARDIAN","PHONE","EMAIL","LINKED CHILDREN",""]}>{parents.map(parent=><tr key={parent.id}><td><div className="student-cell"><Avatar name={parent.parent} colour="peach"/><span>{parent.parent}<small>Parent account · Demo</small></span></div></td><td>{parent.phone}</td><td className="muted-cell">{parent.email}</td><td><span className="count-pill">{students.filter(s=>s.phone===parent.phone).length} child{students.filter(s=>s.phone===parent.phone).length===1?"":"ren"}</span></td><td><button className="text-button" onClick={()=>onUpdate(parent)}><Pencil size={14}/> Update contact</button></td></tr>)}</Table><div className="table-footer"><span>Parent contact edits apply to the linked family in the demo.</span></div></div></>;}

function SchoolSettings({gates,setGates,smsEnabled,setSmsEnabled,appearance,setAppearance,onEdit,onSave,saved}:{gates:{view:boolean;download:boolean};setGates:(v:{view:boolean;download:boolean})=>void;smsEnabled:boolean;setSmsEnabled:(v:boolean)=>void;appearance:SchoolAppearance;setAppearance:(value:SchoolAppearance)=>void;onEdit:()=>void;onSave:()=>void;saved:boolean}){
  const [tab,setTab]=useState("School profile");
  const tabs=["School profile","Appearance","Result gates","Transcript fee","Academic calendar","Grading scale","Notifications","Subscription"];
  return <>
    <PageTitle eyebrow="SCHOOL ACCOUNT" title="School settings" description="Update school details, workspace appearance, access rules and academic preferences." action={<Button onClick={onSave}><Check size={15}/> Save changes</Button>}/>
    <div className="settings-layout"><nav className="settings-menu">{tabs.map(item=><button className={tab===item?"selected":""} key={item} onClick={()=>setTab(item)}>{item}</button>)}</nav>
      <div className="panel settings-body">
        {tab==="School profile" ? <><div className="panel-heading"><div><h2>School information</h2><p>Details shown in the school workspace and on reports.</p></div><Button variant="outline" small onClick={onEdit}><Pencil size={14}/> Edit details</Button></div><div className="school-profile-card"><span className="school-monogram large">B</span><div><strong>{saved?"Bloomfield Academy":"Bloomfield Academy"}</strong><small>Private school · Ikeja, Lagos</small><small>hello@bloomfield.edu.ng · +234 803 555 0100</small></div></div><InfoRows rows={[["School address","14 Independence Avenue, Ikeja, Lagos"],["School type","Primary and Secondary"],["Subdomain","bloomfield.katalysa.ng"],["School logo and stamp","Logo set · Stamp set"]]}/></> : null}
        {tab==="Appearance" ? <><div className="panel-heading"><div><h2>Workspace appearance</h2><p>Use your school colours and choose a comfortable reading size for the workspace.</p></div></div><div className="appearance-grid"><label>Primary colour<input type="color" value={appearance.primary} onChange={event=>setAppearance({...appearance,primary:event.target.value})}/><span>{appearance.primary.toUpperCase()}</span></label><label>Accent colour<input type="color" value={appearance.accent} onChange={event=>setAppearance({...appearance,accent:event.target.value})}/><span>{appearance.accent.toUpperCase()}</span></label></div><div className="font-size-control"><strong>Font size</strong><small>Applies across sign-in and the school workspace.</small><div>{(["small","medium","large"] as const).map(size=><button key={size} className={appearance.fontSize===size?"selected":""} onClick={()=>setAppearance({...appearance,fontSize:size})}>{size[0].toUpperCase()+size.slice(1)}</button>)}</div></div><p className="note">Primary colour replaces the Katalysa navy in the school workspace. Accent colour is used on workspace surfaces; lighter accent colours preserve readability.</p></> : null}
        {tab==="Result gates" ? <><div className="panel-heading"><div><h2>Parent result access</h2><p>Choose whether outstanding fees block result access.</p></div></div><ToggleRow title="Gate result viewing" detail="Parents must clear fees before viewing results." value={gates.view} onChange={value=>setGates({...gates,view:value})}/><ToggleRow title="Gate result downloads" detail="Parents must clear fees before downloading result PDFs." value={gates.download} onChange={value=>setGates({...gates,download:value})}/><p className="note">The real service enforces these gates and returns a specific error code. The parent demo screens reflect these settings locally.</p></> : null}
        {tab==="Transcript fee" ? <><div className="panel-heading"><div><h2>Transcript price</h2><p>One-time purchase per student. Parents can download again after payment.</p></div></div><label className="price-field">Transcript fee (₦)<input type="number" defaultValue="5000"/></label><div className="note">Paystack transaction costs are estimated separately for transcripts. School fee payments remain one combined total.</div></> : null}
        {tab==="Academic calendar" ? <InfoRows rows={[["Academic session","2024/2025"],["First term","23 Sep – 13 Dec 2024"],["Second term","06 Jan – 04 Apr 2025"],["Third term","28 Apr – 25 Jul 2025"],["Active term",activeTerm]]}/> : null}
        {tab==="Grading scale" ? <InfoRows rows={[["A","75–100 · Excellent"],["B","65–74 · Very good"],["C","55–64 · Good"],["D","45–54 · Pass"],["E","40–44 · Fair"],["F","0–39 · Needs improvement"]]}/> : null}
        {tab==="Notifications" ? <><ToggleRow title="Fee payment notifications" detail="Show sample alerts when a payment is logged." value={smsEnabled} onChange={setSmsEnabled}/><ToggleRow title="New enrolment alerts" detail="Notify administrators about new student records." value={!smsEnabled} onChange={value=>setSmsEnabled(!value)}/></> : null}
        {tab==="Subscription" ? <SubscriptionScreen onChoose={()=>onSave()}/> : null}
        <div className="settings-save"><span>{saved?"Changes saved in demo":"Changes are not saved until you click Save changes."}</span><Button onClick={onSave}>Save changes</Button></div>
      </div>
    </div>
  </>;
}
function ToggleRow({title,detail,value,onChange}:{title:string;detail:string;value:boolean;onChange:(v:boolean)=>void}){return <div className="toggle-row"><span><strong>{title}</strong><small>{detail}</small></span><button className={`switch ${value?"on":""}`} role="switch" aria-checked={value} onClick={()=>onChange(!value)}><i/></button></div>;}
function InfoRows({rows}:{rows:[string,string][]}){return <div className="info-rows">{rows.map(([label,value])=><div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>;}

function SubscriptionScreen({onChoose}:{onChoose:(plan:string)=>void}){const plans=[{name:"Starter",price:"₦25,000",limit:"Up to 150 students",features:["Student & teacher records","Classes and terms","Fee tracking","School announcements"]},{name:"Growth",price:"₦45,000",limit:"Up to 500 students",features:["Everything in Starter","Results and report cards","Parent portal","Priority support"],current:true},{name:"Campus",price:"₦85,000",limit:"Unlimited students",features:["Everything in Growth","Multiple campuses","Advanced reports","Dedicated support"]}];return <><PageTitle eyebrow="SCHOOL ACCOUNT" title="Subscription" description="Review the plan for Bloomfield Academy."/><div className="plan-banner"><div><span className="eyebrow">CURRENT PLAN</span><h2>Growth plan · active</h2><p>Next renewal 1 September 2026 · illustrative billing date</p></div><span className="active-chip"><i/>Active</span></div><div className="plan-grid">{plans.map(plan=><article className={`plan-card ${plan.current?"featured":""}`} key={plan.name}>{plan.current&&<span className="current-label">CURRENT PLAN</span>}<span className="plan-name">{plan.name}</span><p>{plan.limit}</p><strong className="plan-price">{plan.price}<small> / month</small></strong><div className="plan-features">{plan.features.map(feature=><span key={feature}><Check size={14}/>{feature}</span>)}</div><Button variant={plan.current?"outline":"primary"} onClick={()=>onChoose(plan.name)}>{plan.current?"Current plan":`Choose ${plan.name}`}</Button></article>)}</div><p className="note">Plan names and prices are illustrative. No subscription checkout or account update is connected.</p></>;}

function TeacherHome({teacherName,assignments,onOpen}:{teacherName:string;assignments:Assignment[];onOpen:()=>void}){const own=assignments.filter(a=>a.subject==="Mathematics");return <><PageTitle title={`Hello, ${teacherName.split(" ")[0]}`} description="Here are your classes and the score entries that need your attention."/><div className="teacher-stat-row"><div><span>MY CLASSES</span><strong>{own.length}</strong></div><div><span>STUDENTS</span><strong>12</strong></div><div><span>RESULTS READY</span><strong>{own.filter(a=>a.complete===a.students).length}/{own.length}</strong></div></div><div className="page-section-heading"><div><h2>My classes</h2><p>Subject and class assignments for this term</p></div><button className="text-button" onClick={onOpen}>View all <ArrowRight size={14}/></button></div><div className="teacher-class-grid">{own.map(item=><TeacherClassCard key={item.id} assignment={item} onOpen={onOpen}/>)}</div><Panel title="What needs attention" subtitle="Finish your scores to help the school publish results"><div className="attention-row"><span className="attention-icon"><ClipboardList size={17}/></span><span><strong>English · JSS 1</strong><small>1 of 2 students still needs a score entry.</small></span><Button small onClick={onOpen}>Continue scores <ArrowRight size={14}/></Button></div></Panel></>;}
function TeacherClassCard({assignment,onOpen}:{assignment:Assignment;onOpen:()=>void}){const percent=Math.round(assignment.complete/assignment.students*100);return <article className="teacher-class-card"><div className="teacher-class-icon"><BookOpen size={18}/></div><span className="count-pill">{assignment.subject}</span><h3>{assignment.className}</h3><p>{assignment.formTeacher?"Class teacher · ":""}{assignment.students} students</p><div className="class-progress"><div><small>Score completion</small><strong>{assignment.complete}/{assignment.students}</strong></div><div className="progress-track"><span style={{width:`${percent}%`}}/></div></div><div className="teacher-card-footer"><span className={percent===100?"complete-text":"incomplete-text"}>{percent===100?<CheckCircle2 size={14}/>:<Activity size={14}/>} {percent===100?"All scores entered":`${percent}% complete`}</span><button aria-label="Open score entry" onClick={onOpen}><ArrowRight size={16}/></button></div></article>;}
function TeacherClasses({assignments,onOpen}:{assignments:Assignment[];onOpen:()=>void}){return <><PageTitle eyebrow="MY TEACHING WORKSPACE" title="My classes" description="Open an assignment to review student scores and completion."/><div className="teacher-class-grid">{assignments.map(item=><TeacherClassCard key={item.id} assignment={item} onOpen={onOpen}/>)}</div><Panel title="Score entry reminder" subtitle="Save often; unsaved changes stay on this page in the live product."><div className="reminder-row"><span className="glance-icon peach"><AlertTriangle size={18}/></span><span>Exam scores of zero should be checked carefully before saving.</span></div></Panel></>;}

function ScoreEntry({values,setValues,assignments,onSave}:{values:Record<string,number>;setValues:(value:Record<string,number>)=>void;assignments:Assignment[];onSave:()=>void}){const [search,setSearch]=useState("");const [notice,setNotice]=useState(false);const current=assignments[0];const students=scoreRows.filter(row=>row.name.toLowerCase().includes(search.toLowerCase()));const complete=students.every(row=>["ca1","ca2","exam"].every(component=>String(values[`${row.studentId}-${component}`]??"").length>0));return <><div className="back-header"><button className="back-link" onClick={()=>history.back()}><ArrowLeft size={15}/> My classes</button><span>{activeTerm}</span></div><PageTitle eyebrow="SCORE ENTRY" title="Mathematics · JSS 1A" description="Enter each student's scores by assessment component." action={<Button variant="outline" onClick={()=>setNotice(true)}><MoreHorizontal size={16}/> Assignment options</Button>}/><div className={`completion-banner ${complete?"complete":""}`}><span>{complete?<CheckCircle2 size={19}/>:<Activity size={18}/>}</span><div><strong>{complete?"You are done.":`${current?.complete||0}/${current?.students||2} complete · Keep going`}</strong><small>{complete?"All visible students have scores in each component.":"Every score component is needed before your assignment is complete."}</small></div><div className="completion-progress"><strong>{complete?"100%":"50%"}</strong><div className="progress-track"><span style={{width:complete?"100%":"50%"}}/></div></div></div>{notice&&<div className="warning-banner"><span><AlertTriangle size={18}/></span><div><strong>Score assignment</strong><small>Mathematics · JSS 1A · Adebayo Okafor · Class Teacher</small></div><button className="icon-action" onClick={()=>setNotice(false)}><X size={16}/></button></div>}<div className="score-toolbar"><SearchField value={search} onChange={setSearch} placeholder="Search students"/><span className="component-pill"><span/>CA1 / 20</span><span className="component-pill"><span/>CA2 / 20</span><span className="component-pill exam"><span/>Exam / 60</span></div><div className="panel no-pad"><Table headers={["STUDENT","CA1 / 20","CA2 / 20","EXAM / 60","STATUS","TEACHER REMARK"]}>{students.map(row=>{const exam=values[`${row.studentId}-exam`];return <tr key={row.studentId}><td><div className="student-cell"><Avatar name={row.name}/><span>{row.name}<small>{row.studentId===1?"BSA/2024/001":"BSA/2024/002"}</small></span></div></td>{(["ca1","ca2","exam"] as const).map(component=><td key={component}><input className="score-input" aria-label={`${row.name} ${component} score`} type="number" min={0} max={component==="exam"?60:20} value={values[`${row.studentId}-${component}`]??""} onChange={e=>setValues({...values,[`${row.studentId}-${component}`]:Number(e.target.value)})}/></td>)}<td><Status value="Done"/></td><td><input className="remark-input" defaultValue={row.remark}/></td>{exam===0&&<td colSpan={6}><div className="zero-warning"><AlertTriangle size={15}/>Exam score is zero for {row.name}. Please verify this is correct.</div></td>}</tr>;})}</Table><div className="score-footer"><span>{students.length} students shown · {complete?"All rows complete":"Scores are not yet complete"}</span><Button onClick={()=>{setNotice(Object.entries(values).some(([key,value])=>key.endsWith("-exam")&&value===0));onSave();}}><Check size={15}/> Save all scores</Button></div></div><p className="note">Scores in this screen are saved to temporary browser state only. The live app returns a warning if an exam score is zero.</p></>;}

function ParentHome({child,children,setChild,fee,gates,announcements,go,onPay,onReceipt}:{child:Student;children:Student[];setChild:(id:number)=>void;fee:Fee;gates:{view:boolean;download:boolean};announcements:Announcement[];go:(p:string)=>void;onPay:(amount:number)=>void;onReceipt:()=>void}){const access=child.status==="active"?"full":child.status==="graduated"?"limited":"minimal";const resultsLocked=(gates.view&&fee.balance>0);const activeChildren=children.length>1;return <><div className="parent-welcome"><div><span className="eyebrow">FAMILY PORTAL · BLOOMFIELD ACADEMY</span><h1>Hello, {child.parent.replace("Mrs ","")} <span>👋</span></h1><p>A clear view of your child’s school week.</p></div><button className="profile-pill" onClick={()=>go("/parent/profile")}><Avatar name={child.parent} colour="gold"/><span>My profile</span><ChevronDown size={14}/></button></div>{activeChildren&&<div className="child-switcher">{children.map(item=><button key={item.id} onClick={()=>setChild(item.id)} className={`child-choice ${child.id===item.id?"selected":""}`}><Avatar name={item.name} colour={item.colour}/><span>{item.name}<small>{item.className}</small></span><Status value={item.status}/></button>)}</div>}{child.status!=="active"&&<div className="limited-banner"><ShieldCheck size={17}/><span><strong>{child.status==="graduated"?"Alumni access":"Limited access"}</strong><small>{child.status==="graduated"?"This student has graduated. Academic history remains available.":"This student's status limits new school updates. Historical fees and results remain accessible."}</small></span></div>}<div className="parent-home-grid"><section className="panel parent-fee-panel"><div className="panel-heading"><div><h2>Fees</h2><p>{activeTerm}</p></div><span className={`status ${fee.balance<=0?"status-paid":"status-partial"}`}><i/>{fee.balance<=0?"Paid":"Partial"}</span></div><div className="parent-balance"><small>Total payable</small><strong>{naira(fee.totalPayable)}</strong></div><div className="balance-breakdown"><div><span>Paid</span><strong>{naira(fee.paid)}</strong></div><div><span>Balance</span><strong className={fee.balance>0?"warning-text":"positive-cell"}>{naira(fee.balance)}</strong></div></div><div className="parent-actions"><Button disabled={fee.balance<=0} onClick={()=>onPay(fee.balance)}><CreditCard size={15}/> Pay now</Button><Button variant="outline" onClick={()=>go("/parent/fees")}>Payment history</Button><button className="icon-button" aria-label="Download payment receipt" onClick={onReceipt}><Download size={16}/></button></div><small className="tiny-note">Total payable includes the school's processing allowance.</small></section><section className="panel parent-results-panel"><div className="panel-heading"><div><h2>Results</h2><p>{activeTerm}</p></div><span className="grade-medal">A</span></div>{resultsLocked?<><div className="locked-result"><span><LockKeyhole size={18}/></span><div><strong>Results are locked</strong><small>Clear the outstanding balance to view results.</small></div></div><div className="locked-balance"><span>Outstanding balance</span><strong>{naira(fee.balance)}</strong></div><Button onClick={()=>onPay(fee.balance)}><CreditCard size={15}/> Pay balance to unlock</Button></>:<><div className="result-preview"><span>Term average<strong>{child.average}%</strong></span><span>Position<strong>2nd of 2</strong></span></div><Button variant="outline" onClick={()=>go("/parent/results")}>View results <ArrowRight size={14}/></Button></>}<button className="download-result" onClick={()=>go("/parent/results")} disabled={gates.download&&fee.balance>0}><Download size={14}/> Download result PDF</button></section></div><div className="parent-lower-grid"><Panel title="School announcements" subtitle="Updates for your family" action={<button className="text-button" onClick={()=>go("/parent/announcements")}>View all <ArrowRight size={14}/></button>}>{access==="full"?announcements.slice(0,2).map(item=><div className="parent-news-row" key={item.id}><span className="news-dot"/><div><strong>{item.title}</strong><small>{item.date} · {item.audience==="all"?"Everyone":"Parents"}</small><p>{item.body}</p></div></div>):<div className="limited-copy">Announcements are not available for this student status. Results and fee history remain visible.</div>}</Panel><Panel title="A little progress goes a long way" subtitle="A snapshot from this term"><div className="progress-card"><span className="progress-illustration"><Sparkles size={20}/></span><div><small>TERM AVERAGE</small><strong>{child.average}%</strong><p>Keep encouraging the steady effort.</p></div><span className="trend-badge">↗ +4%</span></div></Panel></div><p className="parent-privacy"><ShieldCheck size={14}/> You only see information for children linked to your parent account.</p></>;}

function ParentResults({child,fee,gates,onDownload,onPay}:{child:Student;fee:Fee;gates:{view:boolean;download:boolean};onDownload:()=>void;onPay:()=>void}){const blocked=gates.view&&fee.balance>0;const [tab,setTab]=useState(activeTerm);return <><PageTitle eyebrow="PARENT PORTAL · ACADEMIC RECORDS" title={`${child.name}’s results`} description="Published report cards and academic progress." action={<button className="select-pill" onClick={()=>setTab(tab===activeTerm?"Second Term 2024/2025":activeTerm)}><CalendarDays size={15}/>{tab}<ChevronDown size={14}/></button>}/>{blocked?<div className="gate-card"><span className="gate-lock"><LockKeyhole size={21}/></span><span className="eyebrow">FEE GATE · DEMO</span><h2>Results are not available yet.</h2><p>Your child's results are locked until all fees for this term are cleared.</p><div className="gate-balance"><span>Outstanding balance</span><strong>{naira(fee.balance)}</strong></div><Button onClick={onPay}><CreditCard size={15}/> Pay now</Button><small>Error code preview: FEE_GATE_RESULTS · This is a simulated gate response.</small></div>:<><div className="report-card"><div className="report-heading"><span className="school-monogram">B</span><div><strong>Bloomfield Academy</strong><small>Student progress report · {tab}</small></div><button className="button button-outline button-small" disabled={gates.download&&fee.balance>0} onClick={onDownload}><Download size={14}/> Download PDF</button></div><div className="report-student"><div><span>STUDENT</span><strong>{child.name}</strong></div><div><span>CLASS</span><strong>{child.className}</strong></div><div><span>ADMISSION NO.</span><strong>{child.admission}</strong></div><div><span>TERM</span><strong>{tab}</strong></div></div><Table headers={["SUBJECT","CA1","CA2","EXAM","TOTAL","%","GRADE","REMARK"]}>{[["Mathematics",18,15,52,85,"85%","A","Good"],["English Language",17,18,50,85,"85%","A","Excellent"],["Basic Science",19,16,47,82,"82%","A","Very good"],["Social Studies",16,15,42,73,"73%","B","Good"],["Civic Education",18,16,45,79,"79%","A","Very good"]].map(row=><tr key={row[0] as string}>{row.map((cell,i)=><td key={i} className={i===6?"grade-cell":""}>{cell}</td>)}</tr>)}</Table><div className="report-footer"><div><small>OVERALL AVERAGE</small><strong>{child.average}%</strong></div><div><small>POSITION IN CLASS</small><strong>2nd <span>out of 2</span></strong></div><div className="teacher-remark"><small>CLASS TEACHER’S REMARK</small><strong>Consistent effort. Keep up the good work.</strong></div></div></div></>}<p className="note">Only published results are shown. Historical results stay visible to linked parents after graduation or withdrawal.</p></>;}

function ParentFees({child,children,fee,setChild,amount,setAmount,onPay,onHistory,onReceipt}:{child:Student;children:Student[];fee:Fee;setChild:(id:number)=>void;amount:string;setAmount:(v:string)=>void;onPay:()=>void;onHistory:()=>void;onReceipt:()=>void}){const payments=[{date:"23 Aug 2026 · 10:42 AM",amount:25000,method:"Bank transfer",ref:"TRX-•••4821"},{date:"18 Aug 2026 · 3:18 PM",amount:0,method:"Fee assigned",ref:"Second Term"}].filter(x=>x.amount>0);return <><PageTitle eyebrow="PARENT PORTAL · SCHOOL FEES" title="Fees & payments" description="Review the fee balance and payment history for your child." action={children.length>1&&<select className="select-pill" value={child.id} onChange={e=>setChild(Number(e.target.value))}>{children.map(item=><option key={item.id} value={item.id}>{item.name} · {item.className}</option>)}</select>}/><div className="fee-detail-grid"><section className="panel parent-fee-detail"><div className="panel-heading"><div><h2>{child.name}</h2><p>{child.className} · {activeTerm}</p></div><Status value={fee.status}/></div><div className="parent-balance"><small>Total payable</small><strong>{naira(fee.totalPayable)}</strong></div><div className="balance-breakdown"><div><span>Paid so far</span><strong>{naira(fee.paid)}</strong></div><div><span>Outstanding balance</span><strong className={fee.balance>0?"warning-text":"positive-cell"}>{naira(fee.balance)}</strong></div></div><div className="fee-progress-caption"><span>Payment progress</span><strong>{Math.min(100,Math.round(fee.paid/fee.totalPayable*100))}%</strong></div><div className="progress-track"><span style={{width:`${Math.min(100,fee.paid/fee.totalPayable*100)}%`}}/></div>{fee.balance>0?<div className="pay-amount-box"><label>Choose an amount to pay toward your balance<input type="number" value={amount} min="1000" max={fee.balance} onChange={e=>setAmount(e.target.value)}/></label><Button disabled={Number(amount)<=0||Number(amount)>fee.balance} onClick={onPay}><CreditCard size={15}/> Pay {naira(Number(amount)||0)} with Paystack</Button><small>No additional Paystack fee is shown for school-fee payments. The chosen amount goes toward this balance.</small></div>:<div className="fully-paid-banner"><CheckCircle2 size={17}/>This term's fees are fully paid.</div>}</section><aside className="panel payment-help"><span className="payment-help-icon"><ShieldCheck size={20}/></span><h3>Secure payments, clear records.</h3><p>Pay online in one go or in instalments. Your school will see a confirmed payment once processing is complete.</p><div className="help-payment-row"><span>Paystack</span><strong>Card · Bank · USSD</strong></div><button className="text-button" onClick={onHistory}>View payment history <ArrowRight size={14}/></button></aside></div><Panel title="Payment history" subtitle={`${child.name} · confirmed sample payments`} action={<Button variant="outline" small onClick={onReceipt}><Download size={14}/> Download receipt</Button>}><Table headers={["DATE","AMOUNT","METHOD","REFERENCE","STATUS","RECEIPT"]}>{payments.length?payments.map((payment,i)=><tr key={payment.ref}><td>{payment.date}</td><td className="strong-cell">{naira(payment.amount)}</td><td>{payment.method}</td><td className="mono-cell">{payment.ref}</td><td><Status value="Paid"/></td><td><button className="icon-action" aria-label="Download receipt" onClick={onReceipt}><Download size={15}/></button></td></tr>):<tr><td colSpan={6}><Empty title="No payments recorded yet" detail="Payments made to the school will appear here."/></td></tr>}</Table></Panel><p className="note">The live app verifies Paystack confirmation on the backend. This prototype uses a simulated checkout and never records a real payment.</p></>;}

function ParentTranscript({child,onDownload,onPurchase}:{child:Student;onDownload:()=>void;onPurchase:()=>void}){const [from,setFrom]=useState("2021/2022");const [to,setTo]=useState("2023/2024");const [purchased,setPurchased]=useState(false);useEffect(()=>{setPurchased(window.localStorage.getItem(`katalysa-demo-transcript-${child.id}`)==="true");},[child.id]);return <><PageTitle eyebrow="PARENT PORTAL · ACADEMIC RECORDS" title="Academic transcript" description={`Request a full academic history for ${child.name}.`}/>{purchased?<div className="transcript-unlocked"><span><CheckCircle2 size={21}/></span><div><strong>Transcript unlocked</strong><p>This transcript has been purchased in the demo. You can prepare it again at any time.</p></div><Button onClick={onDownload}><Download size={15}/> Download transcript</Button></div>:<div className="transcript-request"><span className="transcript-art"><FileText size={22}/></span><h2>Get {child.name.split(" ")[0]}’s full academic record.</h2><p>Choose a session range if you only need part of the school history. A one-time purchase unlocks unlimited downloads.</p><div className="session-range"><label>From<select value={from} onChange={e=>setFrom(e.target.value)}>{["2021/2022","2022/2023","2023/2024","2024/2025"].map(x=><option key={x}>{x}</option>)}</select></label><ArrowRight size={16}/><label>To<select value={to} onChange={e=>setTo(e.target.value)}>{["2021/2022","2022/2023","2023/2024","2024/2025"].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="itemized transcript-itemized"><div><span>Transcript fee</span><strong>₦5,000</strong></div><div><span>Estimated Paystack charges</span><strong>₦175</strong></div><div className="itemized-total"><span>Total to pay</span><strong>₦5,175</strong></div></div><Button onClick={onPurchase}><CreditCard size={15}/> Pay ₦5,175 with Paystack</Button><small className="checkout-disclaimer"><ShieldCheck size={13}/> Transcript payment is itemized once. No provider is contacted in demo mode.</small></div>}<p className="note">If already purchased, a parent can request the transcript PDF again. A school admin can also record a payment made directly to the school.</p></>;}

function ParentProfile({name,onEdit,onPassword}:{name:string;onEdit:()=>void;onPassword:()=>void}){return <><PageTitle eyebrow="PARENT PORTAL · ACCOUNT" title="My profile" description="Manage your contact details and sign-in settings."/><div className="profile-grid"><Panel title="Personal details" subtitle="The school uses these details to contact your family" action={<Button variant="outline" small onClick={onEdit}><Pencil size={14}/> Edit profile</Button>}><div className="profile-identity"><Avatar name={name} colour="gold"/><div><strong>{name}</strong><small>Parent account · Bloomfield Academy</small></div></div><InfoRows rows={[["Phone number","08077771111 · Contact school to change"],["Email address","mrsokafor@gmail.com"],["Linked children","Tunde Okafor · Sade Okafor"]]}/></Panel><Panel title="Sign-in security" subtitle="Keep your account protected"><div className="security-row"><span className="setup-icon"><KeyRound size={17}/></span><span><strong>Password</strong><small>Change your password regularly.</small></span><Button variant="outline" small onClick={onPassword}>Change password</Button></div><div className="security-row"><span className="setup-icon"><ShieldCheck size={17}/></span><span><strong>School data privacy</strong><small>You can only see linked children and school records.</small></span></div></Panel></div><p className="note">Profile changes are local to this demo. Parent phone number changes should be made by the school administrator.</p></>;}

function NotFound({onHome}:{onHome:()=>void}){return <div className="panel"><Empty title="We couldn’t find that page" detail="Choose one of the available sections from the navigation." action="Go to dashboard" onAction={onHome}/></div>;}






